const e={分组:[{id:"zanghua",名:"黛玉葬花",ids:["zanghua:1","zanghua:2","zanghua:3","zanghua:4","zanghua:5","zanghua:6","zanghua:7","zanghua:8","zanghua:9","zanghua:10","zanghua:11","zanghua:12","zanghua:13","zanghua:14"],回目:[26,27,28],地点:"qinfangzha"},{id:"pudie",名:"宝钗扑蝶",ids:["pudie:1","pudie:2","pudie:3","pudie:4","pudie:5"],回目:[27],地点:"dicui"},{id:"zuiyan",名:"湘云醉眠芍药裀",ids:["zuiyan:1","zuiyan:2","zuiyan:3","zuiyan:4","zuiyan:5"],回目:[62],地点:"hongxiang"},{id:"youyuan",名:"刘姥姥进大观园",ids:["youyuan:1","youyuan:2","youyuan:3","youyuan:4","youyuan:5","youyuan:6"],回目:[40,41],地点:"qinfang"},{id:"haitang",名:"海棠诗社",ids:["haitang:1","haitang:2","haitang:3","haitang:4","haitang:5","haitang:6","haitang:7","haitang:8","haitang:9"],回目:[37],地点:"qiushuang"},{id:"pinchamei",名:"栊翠庵品茶与乞梅",ids:["pinchamei:1","pinchamei:2","pinchamei:3","pinchamei:4","pinchamei:5","pinchamei:6"],回目:[41,50],地点:"longcui"},{id:"lianju",名:"凹晶馆联诗",ids:["lianju:1","lianju:2","lianju:3","lianju:4","lianju:5","lianju:6"],回目:[76],地点:"aojing"},{id:"aida",名:"宝玉挨打",ids:["aida:1","aida:2","aida:3","aida:4","aida:5","aida:6","aida:7","aida:8","aida:9","aida:10","aida:11","aida:12","aida:13","aida:14"],回目:[32,33,34],地点:null},{id:"zhengmen",名:"正门初入",ids:["zhengmen:1","zhengmen:2","zhengmen:3","zhengmen:4"],回目:[17],地点:"gate"},{id:"gexing",名:"芦雪广割腥啖膻",ids:["gexing:1","gexing:2","gexing:3","gexing:4","gexing:5"],回目:[49,50],地点:"luxue"},{id:"zhouru",名:"舟入花溆",ids:["zhouru:1","zhouru:2","zhouru:3","zhouru:4","zhouru:5"],回目:[18,40],地点:"huaxu"},{id:"chufang",名:"柳家的厨房",ids:["chufang:1","chufang:2","chufang:3","chufang:4","chufang:5"],回目:[61,62],地点:"kitchen"},{id:"gongdu",名:"共读西厢",ids:["gongdu:1","gongdu:2","gongdu:3","gongdu:4","gongdu:5"],回目:[23],地点:"qinfangzha"},{id:"qujing",名:"曲径通幽",ids:["qujing:1","qujing:2","qujing:3","qujing:4","qujing:5"],回目:[17],地点:"cuizhang"},{id:"fengao",名:"黛玉焚稿",ids:[],回目:[],地点:"xiaoxiang"},{id:"zilingge",名:"紫菱洲歌",ids:["zilingge:1","zilingge:2","zilingge:3","zilingge:4"],回目:[79],地点:"ziling"},{id:"kanhua",名:"暖香坞看画",ids:["kanhua:1","kanhua:2","kanhua:3","kanhua:4","kanhua:5"],回目:[50],地点:"nuanxiang"},{id:"tianran",名:"稻香村争天然",ids:["tianran:1","tianran:2","tianran:3","tianran:4","tianran:5"],回目:[17],地点:"daoxiang"},{id:"chixie",名:"藕香榭持螯赏桂",ids:["chixie:1","chixie:2","chixie:3","chixie:4","chixie:5"],回目:[38],地点:"ouxiang"},{id:"baiyue",名:"嘉荫堂拜月",ids:["baiyue:1","baiyue:2","baiyue:3","baiyue:4","baiyue:5"],回目:[75],地点:"jiayin"},{id:"zhongqiu",名:"凸碧山庄中秋",ids:["zhongqiu:1","zhongqiu:2","zhongqiu:3","zhongqiu:4","zhongqiu:5","zhongqiu:6"],回目:[75,76],地点:"tubi"},{id:"huaqiang",名:"龄官画蔷",ids:["huaqiang:1","huaqiang:2","huaqiang:3","huaqiang:4","huaqiang:5"],回目:[30],地点:"flowers"},{id:"xuedong",名:"蘅芜苑雪洞",ids:["xuedong:1","xuedong:2","xuedong:3","xuedong:4"],回目:[40],地点:"hengwu"},{id:"shengqin",名:"元妃省亲",ids:["shengqin:1","shengqin:2","shengqin:3","shengqin:4","shengqin:5","shengqin:6"],回目:[18],地点:"xingqin"},{id:"yeyan",名:"寿怡红群芳开夜宴",ids:["yeyan:1","yeyan:2","yeyan:3","yeyan:4","yeyan:5"],回目:[63],地点:"yihong"}],条目:JSON.parse('{"zanghua:1":{"n":"黛玉葬花·第1幅","t":"怡红院门外","册":"zanghua","幅":1,"line":"宝玉被老爷叫去一日，黛玉替他悬心，晚饭后寻来叩门。晴雯正和碧痕拌嘴，问也不问便是一句「都睡下了，明兒再來罷」。一扇门两边都在怄气，门里的人偏不知门外是谁。她并不知道，门里那人此刻也正被旁的心事缠住；误会由一声回话生出，便再无第二声能传过去。","place":"yihong","hui":[26],"img":{"full":"dgy-assets/huace/img/zanghua-01.webp","thumb":"dgy-assets/huace/img/zanghua-01-s.webp"},"画面":"夜里，怡红院门紧闭。黛玉白披风、淡紫立领袄，站在门外抬手叩门，侧耳候着；门里院中，晴雯黑底红点比甲、桃粉袄，背对门嚷着，一脸没好气，碧痕在旁。门内门外分两半构图，中景。","quote":{"文":"再往怡紅院來，只見院門關著，黛玉便以手扣門。","回":26}},"zanghua:2":{"n":"黛玉葬花·第2幅","t":"怡红院墙角","册":"zanghua","幅":2,"line":"她气怔在门外，回思到底是客边，又听院里笑语，竟是宝玉宝钗二人。便不顾苍苔露冷，花径风寒，独立墙角花阴下呜咽起来。连宿鸟栖鸦都飞起远避，不忍再听，书里难得这样替她说一句。听见的笑声是真的，所猜的轻慢却未必是真的；原著偏不替她分辩，让读者同她一起站在冷露里。","place":"yihong","hui":[26],"img":{"full":"dgy-assets/huace/img/zanghua-02.webp","thumb":"dgy-assets/huace/img/zanghua-02-s.webp"},"画面":"怡红院墙角花阴下，黛玉白披风裹身，独立苍苔上，以帕掩面低声呜咽；院内窗纸透出暖黄灯光。附近柳枝花朵上，宿鸟栖鸦扑棱棱惊飞四散。夜景，冷暖对比，中景。","quote":{"文":"只聽裡面一陣笑語之聲，細聽一聽，竟是寶玉『寶釵二人。","回":26}},"zanghua:3":{"n":"黛玉葬花·第3幅","t":"怡红院门外","册":"zanghua","幅":3,"line":"院门一开，出来的是宝钗，宝玉袭人一群人送着。她待要上去问，又怕当着众人羞了他，只得闪过一旁。等门关了，才转过来望着门洒几点泪，这一夜的委屈都落在一扇门上。门开时她有机会问清，礼数与自尊却先把话挡住；这一退，也把后来整夜的辗转留给了自己。","place":"yihong","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-03.webp","thumb":"dgy-assets/huace/img/zanghua-03-s.webp"},"画面":"院门开处，宝钗粉紫织金交领衫被宝玉、袭人一群人送出来，门内灯光透出；黛玉闪在门旁花树影里，白披风半掩，看着众人。门随后关上，她独自望着门落泪。中景，门口亮，黛玉在暗处。","quote":{"文":"話說林黛玉正自悲泣，忽聽院門響處，只見寶釵出來了，寶玉襲人一群人送了出來。待要上去問著寶玉，又恐當著眾人問羞了寶玉不便，因而閃過一旁，讓寶釵去了，寶玉等進去關了門，方轉過來，猶望著門灑了幾點淚。","回":27}},"zanghua:4":{"n":"黛玉葬花·第4幅","t":"潇湘馆","册":"zanghua","幅":4,"line":"回到潇湘馆，她倚着床栏，两手抱膝，好似木雕泥塑的一般，直坐到二更多天。紫鹃雪雁看惯了，也不理论，由她去闷坐。最冷的不是夜，是旁人都看惯了。紫鹃雪雁不劝，并非无情，只是她们也知道这病与心事不能靠一两句话解开。","place":"xiaoxiang","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-04.webp","thumb":"dgy-assets/huace/img/zanghua-04-s.webp"},"画面":"潇湘馆卧房，一盏孤灯。黛玉已卸了残妆，倚着床栏，两手抱膝，眼里含泪，一动不动；外间紫鹃、雪雁各自睡了。窗纱上竹影摇动。夜景，近景，冷色调，人物小而静。","quote":{"文":"紫鵑雪雁素日知道林黛玉的情性：無事悶坐，不是愁眉，便是長歎，且好端端的不知為了什麼，常常的便自淚道不乾的。","回":27}},"zanghua:5":{"n":"黛玉葬花·第5幅","t":"园中","册":"zanghua","幅":5,"line":"芒种这日要祭饯花神，女孩子们用花瓣柳枝编成轿马，用绫锦叠成旌幢，系满了每一枝花。满园绣带飘飖，人人打扮得桃羞杏让。热闹是给花神送行的，独不见那个最惜花的人。花神有轿马，落花却无归处；众人忙着送春，黛玉要做的反是替落花找一块净土。","place":"qinfang","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-05.webp","thumb":"dgy-assets/huace/img/zanghua-05-s.webp"},"画面":"四月二十六日芒种，一早，园中桃柳花树下。几个丫鬟踮脚往花枝上系花瓣柳枝编的轿马、绫锦叠的小旌幢，彩线飘动；远处宝钗一身粉红、凤姐大红窄袄与姊妹们说笑。满园绣带，远景俯视。","quote":{"文":"尚古風俗：凡交芒種節的這日，都要設擺各色禮物，祭餞花神，言芒種一過，便是夏日了，眾花皆卸，花神退位，須要餞行。","回":27}},"zanghua:6":{"n":"黛玉葬花·第6幅","t":"潇湘馆","册":"zanghua","幅":6,"line":"宝玉进门便问「你昨兒可告我了不曾」，黛玉只回头吩咐紫鹃，看那大燕子回来放帘子。他打恭作揖，她正眼也不看，各自出了院门。他记的是昨日中晌，她记的是昨夜那扇门。两人说的明明是同一夜，口中却各有一个昨日；错开的时辰，比争吵更难解释。","place":"xiaoxiang","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-06.webp","thumb":"dgy-assets/huace/img/zanghua-06-s.webp"},"画面":"潇湘馆院中竹下，黛玉淡紫立领袄，刚梳洗出来，回头吩咐紫鹃收拾屋子、放帘子；宝玉大红金莲袍，进门弯腰打恭作揖，满脸赔笑。黛玉正眼不看，径直往院门走。紫鹃青莲紫比甲立在廊下。中景。","quote":{"文":"林黛玉便回頭叫紫鵑道：「把屋子收拾了，撂下一扇紗屜，看那大燕子回來，把帘子放下來，拿獅子倚住，燒了香就把爐罩上。」","回":27}},"zanghua:7":{"n":"黛玉葬花·第7幅","t":"园中","册":"zanghua","幅":7,"line":"黛玉躲开了，宝玉低头只见凤仙石榴落了一地，叹道这是她生了气，连花也不收拾了。他便替她兜了起来，要送到花冢去。赔不是赔不上，便替她做她要做的事，这是宝玉的笨法子。他拾花仍照两人旧日的约定，便是嘴上尚未讲和，手里也不肯辜负她的惜花心。","place":null,"hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-07.webp","thumb":"dgy-assets/huace/img/zanghua-07-s.webp"},"画面":"园中花树下，凤仙、石榴等落花锦重重铺了一地。宝玉独自低头看花，撩起大红袍前襟，弯腰把落花一捧捧兜进衣襟里；远处宝钗一身粉红、探春浅橙黄衫正往外走，回头招呼他。中景，落花红艳。","quote":{"文":"因低頭看見許多鳳仙石榴等各色落花，錦重重的落了一地，因歎道：「這是他心裡生了氣，也不收拾這花兒來了。待我送了去，明兒再問著他。」","回":27}},"zanghua:8":{"n":"黛玉葬花·第8幅","t":"沁芳闸山坡","册":"zanghua","幅":8,"line":"他登山渡水，过树穿花，一直奔到那日同黛玉葬桃花的去处。还没转过山坡，便听见那边有呜咽之声，一行数落着，哭得好不伤感。他只当是哪房的丫头受了委屈，先煞住了脚。这一停，宝玉从寻人变成听人；隔着山坡，先听见的是她不曾当面说出的哀音。","place":"qinfangzha","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-08.webp","thumb":"dgy-assets/huace/img/zanghua-08-s.webp"},"画面":"花冢所在的山坡这一侧，宝玉兜着一襟落花，登到半坡，忽然停步，侧身贴着坡上山石，侧耳倾听；坡那边看不见人，只有花树梢头落英纷纷。中景，山坡斜线把画面一分为二。","quote":{"文":"說畢，等他二人去遠了，便把那花兜了起來，登山渡水，過樹穿花，一直奔了那日同林黛玉葬桃花的去處來。將已到了花冢，猶未轉過山坡，只聽山坡那邊有嗚咽之聲，一行數落著，哭的好不傷感。","回":27}},"zanghua:9":{"n":"黛玉葬花·第9幅","t":"花冢","册":"zanghua","幅":9,"line":"「花謝花飛花滿天，紅消香斷有誰憐」，开口便是满天的花。山坡那边只有她一个，山坡这边也只有他一个。这一首原是吟给落花听的，偏有一个人在听。诗从花的命运起笔，听诗的人尚不知吟者是谁，读者却早知这一声正在替黛玉开口。","place":"qinfangzha","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-09.webp","thumb":"dgy-assets/huace/img/zanghua-09-s.webp"},"画面":"山坡那边花冢旁，一树残花正落。黛玉淡紫立领袄、米白长裙，独立落英之中，一手扶着花锄，一手以帕掩面而泣；锄上挂着花囊，脚下落花满地。山坡这边隐约露出宝玉停步侧耳的半个身影。中景。","quote":{"文":"花謝花飛花滿天，紅消香斷有誰憐？","回":27}},"zanghua:10":{"n":"黛玉葬花·第10幅","t":"花冢","册":"zanghua","幅":10,"line":"「一年三百六十日，風刀霜劍嚴相逼」，说的是花，也是寄人篱下的日子。她独倚花锄，泪洒空枝，竟见了血痕。批一句：葬花的人心里早有一座冢。风霜本是节候，落在这段身世里便有人情的冷暖；吟花时最重的，正是她自己的无处安放。","place":"qinfangzha","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-10.webp","thumb":"dgy-assets/huace/img/zanghua-10-s.webp"},"画面":"黛玉独倚花锄，仰望一树将空的花枝，泪珠一颗颗落下，滴在枝头残瓣上；花囊半满挂在锄头，脚边堆着扫拢的落花。风过处几片花瓣斜飞。近景半身，以空枝与泪痕为焦点。","quote":{"文":"一年三百六十日，風刀霜劍嚴相逼，","回":27}},"zanghua:11":{"n":"黛玉葬花·第11幅","t":"花冢","册":"zanghua","幅":11,"line":"「未若錦囊收艷骨，一抔淨土掩風流」，宁可埋进干净土里，也不叫它落进污淖渠沟。第二十三回她对宝玉说的道理，到这里成了誓。质本洁来还洁去，说的是花，也是她自己。埋花原是一桩小事，到了此处却成了护惜清白的执念；花囊和花锄都承担不起这分重。","place":"qinfangzha","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-11.webp","thumb":"dgy-assets/huace/img/zanghua-11-s.webp"},"画面":"近景，黛玉蹲在花冢前，花锄横放一旁，土坑已挖好；她双手捧起一捧落花，轻轻装进绢囊，再放进坑里。眼含泪，神情却决绝。新翻的泥土，花瓣粉白相间，囊口丝绳垂着。","quote":{"文":"未若錦囊收艷骨，一抔淨土掩風流。","回":27}},"zanghua:12":{"n":"黛玉葬花·第12幅","t":"花冢山坡","册":"zanghua","幅":12,"line":"「儂今葬花人笑痴，他年葬儂知是誰」，一句问到身后去。宝玉在坡上听到这里，不觉恸倒，怀里兜的落花撒了一地。他推及黛玉，推及众人，再推到这园子，原来这一哭是替所有人哭的。花撒了一地，正是手中实物与心里惊惧一齐失守；宝玉这一次听懂的，远不止一首好诗。","place":"qinfangzha","hui":[27],"img":{"full":"dgy-assets/huace/img/zanghua-12.webp","thumb":"dgy-assets/huace/img/zanghua-12-s.webp"},"画面":"前景黛玉站起，仰头望残花，泪流满面，手里捏着一片花瓣；后景山坡上，宝玉大红金莲袍，跌坐坡上，衣襟松开，兜的落花撒了一地，怔怔出神。两人一前一后，隔着山坡互不相见。中景。"},"zanghua:13":{"n":"黛玉葬花·第13幅","t":"花冢山坡","册":"zanghua","幅":13,"line":"她只道人人笑她痴，难道还有一个痴子，抬头一看却是宝玉。「原來是這個狠心短命的」，说到短命二字又把口掩住，长叹一声抽身便走。骂出口的半句是气，咽回去的半句是怕。她先认出他，又立刻转身，说明怨气未散，却也说明最怕的那个结局仍系在他身上。","place":"qinfangzha","hui":[28],"img":{"full":"dgy-assets/huace/img/zanghua-13.webp","thumb":"dgy-assets/huace/img/zanghua-13-s.webp"},"画面":"黛玉闻声抬头，看见坡上的宝玉，脸色一变，一手刚指出去又缩回来掩住口，身子已侧转要走；宝玉仍坐在坡上，泪痕满面，没有察觉。花锄留在冢边。中景，两人隔坡相望的一瞬。","quote":{"文":"那林黛玉正自傷感，忽聽山坡上也有悲聲，心下想道：「人人都笑我有些痴病，難道還有一個痴子不成？」","回":28}},"zanghua:14":{"n":"黛玉葬花·第14幅","t":"回怡红院的路上","册":"zanghua","幅":14,"line":"宝玉在身后叹一句「既有今日，何必當初」，她由不得站住了。听他把从小一处长大的话数落一遍，心内灰了大半，也滴下泪来。昨夜那扇门，原来不是他关的。误会至此才松动，却没有一场痛快的对质；两个人都流泪，仍各自留着未说完的话。","place":null,"hui":[28],"img":{"full":"dgy-assets/huace/img/zanghua-14.webp","thumb":"dgy-assets/huace/img/zanghua-14-s.webp"},"画面":"园中小径上，黛玉在前回过头来，帕子掩着眼角，泪光盈盈；宝玉在身后几步站住，大红袍上沾着泥土，低头叹气，也滴下泪来。路旁残花零落。中景，两人一前一后，中间留一段空路。","quote":{"文":"寶玉在身後面歎道：「既有今日，何必當初！」林黛玉聽見這話，由不得站住，回頭道：「當初怎麼樣？今日怎麼樣？」","回":28}},"pudie:1":{"n":"宝钗扑蝶·第1幅","t":"滴翠亭","册":"pudie","幅":1,"line":"「剛要尋別的姊妹去，忽見前面一雙玉色蝴蝶，大如團扇，一上一下迎風翩躚，十分有趣。寶釵意欲撲了來玩耍，遂向袖中取出扇子來，向草地下來撲。」平日稳重的宝钗，只有这一回像个小姑娘。宝钗原要去潇湘馆找黛玉，见宝玉先进去了，便抽身回来。一对蝴蝶，正好替她遮了这一转身。","place":"dicui","hui":[27],"img":{"full":"dgy-assets/huace/img/pudie-01.webp","thumb":"dgy-assets/huace/img/pudie-01-s.webp"},"画面":"芒种节白天，池边草地。宝钗从袖中取出团扇，轻提裙角，追一对大如团扇的玉色蝴蝶，神情难得地活泼带笑；身后柳枝、远处池中亭子。","quote":{"文":"剛要尋別的姊妹去，忽見前面一雙玉色蝴蝶，大如團扇，一上一下迎風翩躚，十分有趣。寶釵意欲撲了來玩耍，遂向袖中取出扇子來，向草地下來撲。","回":27}},"pudie:2":{"n":"宝钗扑蝶·第2幅","t":"滴翠亭","册":"pudie","幅":2,"line":"「寶釵也無心撲了，剛欲回來，只聽滴翠亭裡邊嘁嘁喳喳有人說話。原來這亭子四面俱是遊廊曲橋，蓋造在池中水上，四面雕鏤隔子糊著紙。」隔扇是糊纸的，里面说什么外面全听得见。隔扇糊的是纸，话是关不住的。这园里本没有真私话，到抄检那一回便知（第74回）。","place":"dicui","hui":[27],"img":{"full":"dgy-assets/huace/img/pudie-02.webp","thumb":"dgy-assets/huace/img/pudie-02-s.webp"},"画面":"游廊曲桥尽头的水上亭子，四面雕花隔扇糊着纸。宝钗停在亭外桥上，扇子垂在身侧，微微侧头，屏息听里面说话；蝴蝶已飞远。","quote":{"文":"寶釵也無心撲了，剛欲回來，只聽滴翠亭裡邊嘁嘁喳喳有人說話。原來這亭子四面俱是遊廊曲橋，蓋造在池中水上，四面雕鏤隔子糊著紙。","回":27}},"pudie:3":{"n":"宝钗扑蝶·第3幅","t":"滴翠亭","册":"pudie","幅":3,"line":"「猶未想完，只聽「咯吱」一聲，寶釵便故意放重了腳步，笑著叫道：「顰兒，我看你往那裡藏！」一面說，一面故意往前趕。」她心里想的是使个“金蝉脱壳”的法子，喊“颦儿”就是装作在找黛玉。窗子一响，她只来得及想一个名字，想到的是颦儿。急中脱口的，偏是平日最该避开的那个人。","place":"dicui","hui":[27],"img":{"full":"dgy-assets/huace/img/pudie-03.webp","thumb":"dgy-assets/huace/img/pudie-03-s.webp"},"画面":"亭子一扇窗刚被推开，露出红玉、坠儿两个丫鬟吃惊的脸。宝钗在桥上故意加重脚步往前赶，回头笑着朝远处喊，像在追人。","quote":{"文":"猶未想完，只聽「咯吱」一聲，寶釵便故意放重了腳步，笑著叫道：「顰兒，我看你往那裡藏！」一面說，一面故意往前趕。","回":27}},"pudie:4":{"n":"宝钗扑蝶·第4幅","t":"滴翠亭","册":"pudie","幅":4,"line":"「我才在河那邊看著林姑娘在這裡蹲著弄水兒的。我要悄悄的唬他一跳，還沒有走到跟前，他倒看見我了，朝東一繞就不見了。」黛玉这时根本不在这里，这是宝钗随口编的。蹲着，弄水，朝东一绕，说得有鼻子有眼。急中生出的一句谎，也编得这样周全，这是宝钗的应变。","place":"dicui","hui":[27],"img":{"full":"dgy-assets/huace/img/pudie-04.webp","thumb":"dgy-assets/huace/img/pudie-04-s.webp"},"画面":"亭内，宝钗笑盈盈地四下张望、掀帘作寻人状，红玉、坠儿怔怔站着，脸色发白。","quote":{"文":"我才在河那邊看著林姑娘在這裡蹲著弄水兒的。我要悄悄的唬他一跳，還沒有走到跟前，他倒看見我了，朝東一繞就不見了。","回":27}},"pudie:5":{"n":"宝钗扑蝶·第5幅","t":"滴翠亭","册":"pudie","幅":5,"line":"「紅玉道：「若是寶姑娘聽見，還倒罷了。林姑娘嘴裡又愛刻薄人，心裡又細，他一聽見了，倘或走露了風聲，怎麼樣呢？」」她们怕的是黛玉，不是宝钗——宝钗这一招，脱了身，也把偷听的嫌疑推给了黛玉。红玉怕的是走露风声，转眼却被凤姐唤去使唤，攀了高枝。同一回里，她的运道走得比谁都快。","place":"dicui","hui":[27],"img":{"full":"dgy-assets/huace/img/pudie-05.webp","thumb":"dgy-assets/huace/img/pudie-05-s.webp"},"画面":"宝钗已走远。亭内红玉拉着坠儿的手，两人凑近低声说话，满脸惊慌；窗外池水平静。","quote":{"文":"紅玉道：「若是寶姑娘聽見，還倒罷了。林姑娘嘴裡又愛刻薄人，心裡又細，他一聽見了，倘或走露了風聲，怎麼樣呢？」","回":27}},"zuiyan:1":{"n":"湘云醉眠芍药裀·第1幅","t":"红香圃","册":"zuiyan","幅":1,"line":"「頑了一回，大家方起席散了一散，倏然不見了湘雲，只當他外頭自便就來，誰知越等越沒了影響，使人各處去找，那裡找得著。」散席时大家才发现，湘云不见了。席上她头一个等不得，和宝玉三五乱叫地划拳，散席时偏不见了人。老太太太太不在家，园里连找人都找得热闹。","place":"hongxiang","hui":[62],"img":{"full":"dgy-assets/huace/img/zuiyan-01.webp","thumb":"dgy-assets/huace/img/zuiyan-01-s.webp"},"画面":"芍药栏中红香圃三间小敞厅，寿宴将散，杯盘狼藉。众姐妹起身四顾，丫鬟们分头出去找人，神情又好笑又着急——湘云不见了。","quote":{"文":"頑了一回，大家方起席散了一散，倏然不見了湘雲，只當他外頭自便就來，誰知越等越沒了影響，使人各處去找，那裡找得著。","回":62}},"zuiyan:2":{"n":"湘云醉眠芍药裀·第2幅","t":"红香圃","册":"zuiyan","幅":2,"line":"「說著，都走來看時，果見湘雲臥於山石僻處一個石凳子上，業經香夢沉酣，四面芍藥花飛了一身，滿頭臉衣襟上皆是紅香散亂，手中的扇子在地下，也半被落花埋了，一群蜂蝶鬧穰穰的圍著他，又用鮫帕包了一包芍藥花瓣枕著。」回目叫“芍药裀”（花铺的褥子），其实她睡的是石凳，身上盖的是落花。蜂蝶围着，红香满身，这是园里最无忧的一觉。曲子里的「雲散高唐，水涸湘江」，此刻还远（第5回）。","place":"hongxiang","hui":[62],"img":{"full":"dgy-assets/huace/img/zuiyan-02.webp","thumb":"dgy-assets/huace/img/zuiyan-02-s.webp"},"画面":"山石后僻静处，一条青石凳上，湘云侧身酣睡，满头满身落着芍药花瓣，手里的扇子掉在地上半埋进落花，头下枕着一包用手帕包起的花瓣，一群蜂蝶绕着她飞；脸颊酒红，睡得香甜。","quote":{"文":"說著，都走來看時，果見湘雲臥於山石僻處一個石凳子上，業經香夢沉酣，四面芍藥花飛了一身，滿頭臉衣襟上皆是紅香散亂，手中的扇子在地下，也半被落花埋了，一群蜂蝶鬧穰穰的圍著他，又用鮫帕包了一包芍藥花瓣枕著。","回":62}},"zuiyan:3":{"n":"湘云醉眠芍药裀·第3幅","t":"红香圃","册":"zuiyan","幅":3,"line":"「泉香而酒冽，玉碗盛來琥珀光，直飲到梅梢月上，醉扶歸，卻為宜會親友。」睡着了嘴里念的还是席上的酒令。梦里一句话凑齐了古文、旧诗、骨牌、曲牌、时宪书，五样不缺。人醉了，令倒没乱。众人先听见她念念有词，再到山石后寻人；席上的喧声已远，席上的兴致却被她带进了梦里。","place":"hongxiang","hui":[62],"img":{"full":"dgy-assets/huace/img/zuiyan-03.webp","thumb":"dgy-assets/huace/img/zuiyan-03-s.webp"},"画面":"同一处，众姐妹围在石凳边掩口而笑，有人伸手推她；湘云闭着眼，嘴唇微动，还在说梦话。","quote":{"文":"泉香而酒冽，玉碗盛來琥珀光，直飲到梅梢月上，醉扶歸，卻為宜會親友。","回":62}},"zuiyan:4":{"n":"湘云醉眠芍药裀·第4幅","t":"红香圃","册":"zuiyan","幅":4,"line":"「湘雲慢啟秋波，見了眾人，低頭看了一看自己，方知是醉了。原是來納涼避靜的，不覺的因多罰了兩杯酒，嬌嫋不勝，便睡著了，心中反覺自愧。」她本来只是想找个凉快地方躲一躲。平日大说大笑的人，这会子也知道低头。娇袅二字，书里难得落在湘云身上。","place":"hongxiang","hui":[62],"img":{"full":"dgy-assets/huace/img/zuiyan-04.webp","thumb":"dgy-assets/huace/img/zuiyan-04-s.webp"},"画面":"湘云刚睁开眼，半撑起身子，低头看自己一身花瓣，有点不好意思地笑；众人围着看她。","quote":{"文":"湘雲慢啟秋波，見了眾人，低頭看了一看自己，方知是醉了。原是來納涼避靜的，不覺的因多罰了兩杯酒，嬌嫋不勝，便睡著了，心中反覺自愧。","回":62}},"zuiyan:5":{"n":"湘云醉眠芍药裀·第5幅","t":"红香圃","册":"zuiyan","幅":5,"line":"「探春忙命將醒酒石拿來給他銜在口內，一時又命他喝了一些酸湯，方才覺得好了些。」醒酒石是含在嘴里解酒的石头。醒酒石、酸汤，都是探春吩咐的。这阵子她替凤姐理家，席上席下的事，样样想在头里。看完众人的笑，还须看谁替醉者收拾残局；花下那场自在，终要回到有人照应的日常。","place":"hongxiang","hui":[62],"img":{"full":"dgy-assets/huace/img/zuiyan-05.webp","thumb":"dgy-assets/huace/img/zuiyan-05-s.webp"},"画面":"回到红香圃敞厅里，湘云坐着，鬓边还粘着花瓣；探春递来一块醒酒石让她含在嘴里，丫鬟端着一碗酸汤候着。","quote":{"文":"探春忙命將醒酒石拿來給他銜在口內，一時又命他喝了一些酸湯，方才覺得好了些。","回":62}},"youyuan:1":{"n":"刘姥姥进大观园·第1幅","t":"沁芳亭","册":"youyuan","幅":1,"line":"「一語未完，鳳姐便拉過劉姥姥，笑道：「讓我打扮你。」說著，將一盤子花橫三豎四的插了一頭。賈母和眾人笑的了不得。」她不恼，反说“今儿老风流才好”——一开场就把大家逗乐了。满头的花是凤姐插的，这一天的差事，鸳鸯早叫破了，「女篾片」。肯戴这一头花，才是刘姥姥的本事。","place":"qinfang","hui":[40],"img":{"full":"dgy-assets/huace/img/youyuan-01.webp","thumb":"dgy-assets/huace/img/youyuan-01-s.webp"},"画面":"秋日上午，沁芳亭一带。丫鬟捧着荷叶式翡翠盘，盘里是各色折枝菊花；凤姐笑着把菊花横三竖四插满刘姥姥一头，贾母鬓边簪着一朵大红菊，众人笑弯了腰，刘姥姥咧着缺牙的嘴也跟着笑。","quote":{"文":"一語未完，鳳姐便拉過劉姥姥，笑道：「讓我打扮你。」說著，將一盤子花橫三豎四的插了一頭。賈母和眾人笑的了不得。","回":40}},"youyuan:2":{"n":"刘姥姥进大观园·第2幅","t":"潇湘馆","册":"youyuan","幅":2,"line":"「他只顧上頭和人說話，不防底下果踩滑了，咕咚一跤跌倒。眾人拍手都哈哈的笑起來。」琥珀刚提醒“仔细苍苔滑了”，她说“我们走熟了的”，话音没落就摔了。跌完一跤，进屋看了一眼，便说「竟比那上等的書房還好」。乡下人一句话，把黛玉的住处说准了。","place":"xiaoxiang","hui":[40],"img":{"full":"dgy-assets/huace/img/youyuan-02.webp","thumb":"dgy-assets/huace/img/youyuan-02-s.webp"},"画面":"潇湘馆院里，两边翠竹夹路，中间一条石子小路，地上满是青苔。刘姥姥让开石子路，自己走在青苔土上，一边回头和人说话，脚下一滑咕咚摔倒；众人拍手大笑。","quote":{"文":"他只顧上頭和人說話，不防底下果踩滑了，咕咚一跤跌倒。眾人拍手都哈哈的笑起來。","回":40}},"youyuan:3":{"n":"刘姥姥进大观园·第3幅","t":"秋爽斋","册":"youyuan","幅":3,"line":"「賈母這邊說聲「請」，劉姥姥便站起身來，高聲說道：「老劉，老劉，食量大似牛，吃一個老母豬不抬頭。」自己卻鼓著腮不語。」这是鸳鸯、凤姐事先教好的。她心里明白，事后说“你先嘱咐我，我就明白了”。笑声未落，她又和鸽子蛋较上劲。「一兩銀子，也沒聽見響聲兒就沒了」，满桌笑声里，银子落地的声儿只有她听得见。","place":"qiushuang","hui":[40],"img":{"full":"dgy-assets/huace/img/youyuan-03.webp","thumb":"dgy-assets/huace/img/youyuan-03-s.webp"},"画面":"秋爽斋晓翠堂，摆着长桌宴席。刘姥姥站起身高声说话，说完鼓着腮帮子一声不吭；满座笑翻：湘云喷饭，黛玉伏桌笑岔气，宝玉滚进贾母怀里，探春的饭碗扣在迎春身上。","quote":{"文":"賈母這邊說聲「請」，劉姥姥便站起身來，高聲說道：「老劉，老劉，食量大似牛，吃一個老母豬不抬頭。」自己卻鼓著腮不語。","回":40}},"youyuan:4":{"n":"刘姥姥进大观园·第4幅","t":"栊翠庵","册":"youyuan","幅":4,"line":"「賈母便吃了半盞，便笑著遞與劉姥姥說：「你嘗嘗這個茶。」劉姥姥便一口吃盡，笑道：「好是好，就是淡些，再熬濃些更好了。」」妙玉事后叫把这只杯子搁在外头，不要了。她嫌淡的这一钟，转眼成了妙玉嫌脏的杯子。宝玉替她讨了来，说「他賣了也可以度日」。","place":"longcui","hui":[41],"img":{"full":"dgy-assets/huace/img/youyuan-04.webp","thumb":"dgy-assets/huace/img/youyuan-04-s.webp"},"画面":"栊翠庵院中，贾母坐着，把一只成窑五彩小盖钟递给刘姥姥；刘姥姥仰头一口喝干，咂嘴说淡；妙玉立在一旁，面无表情；众人在笑。","quote":{"文":"賈母便吃了半盞，便笑著遞與劉姥姥說：「你嘗嘗這個茶。」劉姥姥便一口吃盡，笑道：「好是好，就是淡些，再熬濃些更好了。」","回":41}},"youyuan:5":{"n":"刘姥姥进大观园·第5幅","t":"省亲别墅","册":"youyuan","幅":5,"line":"「眾人笑道：「你認得這是什麼廟？」劉姥姥便抬頭指那字道：「這不是『玉皇寶殿』四字？」」牌坊上写的是“省亲别墅”，她把这里当成了大庙。认错了字，没认错地方。贵妃回来一夜便走，这座殿原本就是供着的。旁人笑她不识匾额，她却照着自己的生活经验跪了下去；同一座院宇，富贵人家与乡下客人看见的不是一回事。","place":"xingqin","hui":[41],"img":{"full":"dgy-assets/huace/img/youyuan-05.webp","thumb":"dgy-assets/huace/img/youyuan-05-s.webp"},"画面":"省亲别墅的石牌坊下，刘姥姥趴在地上磕头，又抬头指着牌坊上的字，一脸认真；身后众人笑得拍手跺脚。","quote":{"文":"眾人笑道：「你認得這是什麼廟？」劉姥姥便抬頭指那字道：「這不是『玉皇寶殿』四字？」","回":41}},"youyuan:6":{"n":"刘姥姥进大观园·第6幅","t":"怡红院","册":"youyuan","幅":6,"line":"「他此時又帶了七八分醉，又走乏了，便一屁股坐在床上，只說歇歇，不承望身不由己，前仰後合的，朦朧著兩眼，一歪身就睡熟在床上。」她迷了路，误打误撞睡在了宝玉的床上；袭人找到她，只对外说她在草地上睡着了。镜里撞见自己，还当是亲家母，笑她「沒死活戴了一頭」。笑人的和挨笑的，原是一个人。","place":"yihong","hui":[41],"img":{"full":"dgy-assets/huace/img/youyuan-06.webp","thumb":"dgy-assets/huace/img/youyuan-06-s.webp"},"画面":"怡红院宝玉卧室，精致的床帐，旁边一面西洋穿衣镜刚被撞开。刘姥姥带着七八分醉，满头还插着花，一歪身倒在床上睡熟，鼾声大作。","quote":{"文":"他此時又帶了七八分醉，又走乏了，便一屁股坐在床上，只說歇歇，不承望身不由己，前仰後合的，朦朧著兩眼，一歪身就睡熟在床上。","回":41}},"haitang:1":{"n":"海棠诗社·第1幅","t":"洒泪亭","册":"haitang","幅":1,"line":"贾政点了学差，八月二十日起身，子弟们一直送到洒泪亭。老爷一走，园子里便没人管了，宝玉每日任意纵性的逛荡。可知天下的诗社，多半是在严父出门那一日开张的。父亲离园不是诗社的题面，却是众人能聚在秋爽斋的一层因由，闲日才忽然有了空处。","place":null,"hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-01.webp","thumb":"dgy-assets/huace/img/haitang-01-s.webp"},"画面":"八月二十日，城外洒泪亭。贾政月白浅灰蓝袍，正要登车，回身叮嘱；宝玉浅金褐团花袍，与贾环、贾兰等子弟垂手站成一排送行。车马行李在亭外候着，秋树疏朗。远中景，人物小。","quote":{"文":"這年賈政又點了學差，擇於八月二十日起身。是日拜過宗祠及賈母起身，寶玉諸子弟等送至灑淚亭。","回":37}},"haitang:2":{"n":"海棠诗社·第2幅","t":"怡红院","册":"haitang","幅":2,"line":"正无聊之际，翠墨送来一副花笺，是探春亲笔。笺上说「孰謂蓮社之雄才，獨許鬚眉」，要邀众姊妹结社。宝玉看了拍手便走，三妹妹一纸帖子，把一园的闲人都请动了。探春不等别人提议，先写帖、先邀人，起社的主心骨便在这张小小花笺上。","place":"yihong","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-02.webp","thumb":"dgy-assets/huace/img/haitang-02-s.webp"},"画面":"秋日，怡红院屋里，宝玉浅金褐团花袍，百无聊赖歪在榻上；丫鬟翠墨进门，双手递上一副花笺。宝玉坐直身子展开来看，脸上渐渐露出喜色，作势要起身。近景，窗外芭蕉海棠。","quote":{"文":"這日正無聊之際，只見翠墨進來，手裡拿著一副花箋送與他。","回":37}},"haitang:3":{"n":"海棠诗社·第3幅","t":"沁芳亭","册":"haitang","幅":3,"line":"才到沁芳亭，后门婆子又送来一张帖，是贾芸写给他这个干爹的帖子，说寻得两盆白海棠。「不肖男芸恭請父親大人萬福金安」，宝玉看了只是笑。诗社还没起，诗题倒先自己送上门来。一张亲笔邀帖接一张滑稽回帖，花与人的因缘几乎同时送到，叙事也由此轻快起来。","place":"qinfang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-03.webp","thumb":"dgy-assets/huace/img/haitang-03-s.webp"},"画面":"沁芳亭桥头，宝玉浅金褐团花袍，与翠墨正往秋爽斋去；一个守后门的婆子迎上来，递过一张字帖。宝玉展开一看，忍不住笑出声，翠墨在旁探头。亭外秋水，柳叶微黄。中景，字帖为焦点。","quote":{"文":"不肖男芸恭請父親大人萬福金安。","回":37}},"haitang:4":{"n":"海棠诗社·第4幅","t":"秋爽斋","册":"haitang","幅":4,"line":"众人见宝玉进来，笑说又来了一个，探春道一招皆到。李纨进门便说「雅的緊！要起詩社，我自薦我掌壇」。她自称不会作诗，掌坛却当仁不让，这是寡居的人难得的一点兴头。李纨先定掌坛，给这场游戏立下规矩；有了她在场，少年人的兴头才有了可持续的章法。","place":"qiushuang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-04.webp","thumb":"dgy-assets/huace/img/haitang-04-s.webp"},"画面":"秋爽斋屋里，宝钗杏黄袄、黛玉淡紫袄、迎春姜黄褙子、惜春藕荷袄已坐下，探春浅橙黄交领衫起身笑迎宝玉；李纨雪青蓝褙子掀帘进门，满面笑意抬手说话。窗外梧桐芭蕉。中景群像。","quote":{"文":"探春笑道：「我不算俗，偶然起個念頭，寫了幾個帖兒試一試，誰知一招皆到。」","回":37}},"haitang:5":{"n":"海棠诗社·第5幅","t":"秋爽斋","册":"haitang","幅":5,"line":"探春自号蕉下客，黛玉便要众人牵了她去炖脯子吃酒，可不是一只鹿了。探春也不饶，说她住潇湘馆又爱哭，竹子将来也要变成斑竹，就叫「瀟湘妃子」。一笑一谶，黛玉低了头，竟不言语了。号本是玩笑，偏在笑声里分出了各人的眼光：探春爽利，黛玉敏捷，也各有一处不愿人触的心事。","place":"qiushuang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-05.webp","thumb":"dgy-assets/huace/img/haitang-05-s.webp"},"画面":"窗外一丛芭蕉。探春刚说完自己的号，黛玉掩口笑着指她打趣，众人哄笑；探春佯嗔，转身向众人说话，黛玉随即低了头。宝玉在旁拍手叫妙。中景，芭蕉叶大片入画。","quote":{"文":"他自稱『蕉下客』，可不是一隻鹿了？","回":37}},"haitang:6":{"n":"海棠诗社·第6幅","t":"秋爽斋","册":"haitang","幅":6,"line":"李纨封宝钗作蘅芜君，宝钗却回送宝玉一个号，说天下难得是富贵，又难得是闲散，你兼有了，就叫「富貴閒人」。宝玉连说当不起。旁人起号是雅，宝钗起号是看人看到了根上。名号看似轻巧，实则让同在一园的人重新相认；一场诗社从此有了自己的称谓与座次。","place":"qiushuang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-06.webp","thumb":"dgy-assets/huace/img/haitang-06-s.webp"},"画面":"宝钗杏黄袄端坐含笑，侧身对宝玉说话；宝玉浅金褐团花袍，连连拱手推辞，笑着作揖。李纨坐在上首点头，迎春、惜春相视而笑。中景，宝钗一坐、宝玉一立，金锁在宝钗胸前显眼。","quote":{"文":"寶釵道：「還得我送你個號罷。有最俗的一個號，卻於你最當。天下難得的是富貴，又難得的是閒散，這兩樣再不能兼有，不想你兼有了，就叫你『富貴閒人』也罷了。」","回":37}},"haitang:7":{"n":"海棠诗社·第7幅","t":"秋爽斋","册":"haitang","幅":7,"line":"李纨说抬进来两盆白海棠，就咏它罢。迎春随手一揭是七言律，又叫倚门的小丫头随口说一个字，偏是个门字。宝玉直叫这两个字不好作，限韵的人不会作诗，难为的是会作诗的人。题、体、韵全由众人临时凑成，所谓雅集并非预排好的盛事，趣味正在众手推着往前走。","place":"qiushuang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-07.webp","thumb":"dgy-assets/huace/img/haitang-07-s.webp"},"画面":"书架前，迎春姜黄褙子随手抽出一本诗集翻开；倚门站着的小丫头张口说了一个字，迎春回头笑着点头。案上韵牌匣子打开，露出几块韵牌。探春、宝玉围过来看。中景。","quote":{"文":"迎春掩了詩，又向一個小丫頭道：「你隨口說一個字來。」","回":37}},"haitang:8":{"n":"海棠诗社·第8幅","t":"秋爽斋回廊","册":"haitang","幅":8,"line":"一支梦甜香燃着，香尽未成便要罚。探春先有了，宝钗也誊了，宝玉在回廊上踱来踱去，独黛玉或抚梧桐，或看秋色。急的急，闲的闲，诗还没写出来，各人的性情倒先写出来了。香灰一寸寸落下，纸上未有定稿，廊下却已是一幅人物画；谁急谁闲，先于诗句给出了答案。","place":"qiushuang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-08.webp","thumb":"dgy-assets/huace/img/haitang-08-s.webp"},"画面":"案上一支三寸来长的梦甜香已燃去大半。探春伏案改抹诗稿，宝钗已在誊写；宝玉背着手在回廊上踱来踱去；黛玉淡紫袄、白披风，一手抚着廊外梧桐，看秋色出神。中景，回廊横贯画面。","quote":{"文":"獨黛玉或撫梧桐，或看秋色，或又和丫鬟們嘲笑。","回":37}},"haitang:9":{"n":"海棠诗社·第9幅","t":"秋爽斋","册":"haitang","幅":9,"line":"宝钗诗里一句「淡極始知花更艷」，李纨看了便笑道到底是蘅芜君。她说有却有了，只是不好，交出来的偏是最稳的一首。淡到极处方见颜色，说的是海棠，更像说她自己。李纨的评次不是一句输赢，而是把含蓄与别致分开看；同咏白花，几个人的笔下竟各有颜色。","place":"qiushuang","hui":[37],"img":{"full":"dgy-assets/huace/img/haitang-09.webp","thumb":"dgy-assets/huace/img/haitang-09-s.webp"},"画面":"李纨雪青蓝褙子坐在上首，手执宝钗的诗笺细看，点头称许；宝钗杏黄袄、玫瑰粉裙，端坐含笑不语；探春凑近同看，宝玉在旁张望。案上一炉残香。中近景，诗笺为焦点。","quote":{"文":"胭脂洗出秋階影，冰雪招來露砌魂。","回":37}},"pinchamei:1":{"n":"栊翠庵品茶与乞梅·第1幅","t":"栊翠庵","册":"pinchamei","幅":1,"line":"「妙玉笑往裡讓，賈母道：「我們才都吃了酒肉，你這裡頭有菩薩，沖了罪過。我們這裡坐坐，把你的好茶拿來，我們吃一杯就去了。」」刚在园里喝过酒吃过肉，贾母知礼，不进佛堂。老太太年高位尊，偏守着佛门规矩不进去。门外这一站，比进去还见得敬重。","place":"longcui","hui":[41],"img":{"full":"dgy-assets/huace/img/pinchamei-01.webp","thumb":"dgy-assets/huace/img/pinchamei-01-s.webp"},"画面":"秋日，栊翠庵东禅堂外，花木繁盛。贾母带着众人停在门外，摆手不肯进去，笑着说话；妙玉站在门边让客，神情恭谨而冷淡。","quote":{"文":"妙玉笑往裡讓，賈母道：「我們才都吃了酒肉，你這裡頭有菩薩，沖了罪過。我們這裡坐坐，把你的好茶拿來，我們吃一杯就去了。」","回":41}},"pinchamei:2":{"n":"栊翠庵品茶与乞梅·第2幅","t":"栊翠庵","册":"pinchamei","幅":2,"line":"「妙玉笑說：「知道。這是老君眉。」」贾母先说“我不吃六安茶”，妙玉早有准备，泡的是老君眉，水用的是旧年雨水。出家的人，把老太太不吃六安茶记得这样准。槛外人做起人情来，比槛内的还周全。她记得来客的口味，再递上自己备好的茶；一盏茶里既有待客的敬意，也有不肯随俗的主张。","place":"longcui","hui":[41],"img":{"full":"dgy-assets/huace/img/pinchamei-02.webp","thumb":"dgy-assets/huace/img/pinchamei-02-s.webp"},"画面":"妙玉双手捧一个海棠花式雕漆小茶盘，盘里一只成窑五彩小盖钟，躬身递给贾母；贾母正要开口。","quote":{"文":"妙玉笑說：「知道。這是老君眉。」","回":41}},"pinchamei:3":{"n":"栊翠庵品茶与乞梅·第3幅","t":"栊翠庵","册":"pinchamei","幅":3,"line":"「仍將前番自己常日吃茶的那隻綠玉斗來斟與寶玉。寶玉笑道：「常言『世法平等』，他兩個就用那樣古玩奇珍，我就是個俗器了。」」给宝玉的，偏是她自己天天用的那只。两个姑娘用的是古玩，宝玉用的是她日常的绿玉斗。她偏说「獨你來了，我是不給你吃的」，越撇越撇不清。","place":"longcui","hui":[41],"img":{"full":"dgy-assets/huace/img/pinchamei-03.webp","thumb":"dgy-assets/huace/img/pinchamei-03-s.webp"},"画面":"栊翠庵耳房，陈设清简。宝钗坐在榻上，黛玉坐在蒲团上，各捧一只古雅奇特的杯子；妙玉执壶，给刚溜进来的宝玉斟一只碧绿的玉斗，宝玉笑着说话。","quote":{"文":"仍將前番自己常日吃茶的那隻綠玉斗來斟與寶玉。寶玉笑道：「常言『世法平等』，他兩個就用那樣古玩奇珍，我就是個俗器了。」","回":41}},"pinchamei:4":{"n":"栊翠庵品茶与乞梅·第4幅","t":"栊翠庵","册":"pinchamei","幅":4,"line":"「豈不聞『一杯為品，二杯即是解渴的蠢物，三杯便是飲牛飲騾了』。你吃這一海便成什麼？」话虽刻薄，她还是只给他斟了一杯。一杯为品，三杯饮骡，论的是茶，嘲的是宝玉。他依言细细吃了，「果覺輕浮無比」，乖得很。耳房里明明是请人品茶，她却偏用锋利的话定下规矩；宝钗、黛玉在旁听着，谁也不能把这一席当作寻常的待客闲谈。","place":"longcui","hui":[41],"img":{"full":"dgy-assets/huace/img/pinchamei-04.webp","thumb":"dgy-assets/huace/img/pinchamei-04-s.webp"},"画面":"同一耳房，妙玉手里托着一只竹根整雕、盘曲如虬的大茶盒，似笑非笑地看宝玉；宝钗、黛玉、宝玉都笑了。","quote":{"文":"豈不聞『一杯為品，二杯即是解渴的蠢物，三杯便是飲牛飲騾了』。你吃這一海便成什麼？","回":41}},"pinchamei:5":{"n":"栊翠庵品茶与乞梅·第5幅","t":"芦雪广","册":"pinchamei","幅":5,"line":"「可厭妙玉為人，我不理他。如今罰你去取一枝來。」宝玉联句落了第，罚他去栊翠庵讨红梅。厌其人，爱其梅，李纨这一罚，公私两便。满园都明白，这枝梅只有宝玉讨得来。诗已联完，输的人还要踏雪出门；他去的不是花圃，而是众人平日不轻易走近的庵门，罚题便成了另一场试探。","place":"luxue","hui":[50],"img":{"full":"dgy-assets/huace/img/pinchamei-05.webp","thumb":"dgy-assets/huace/img/pinchamei-05-s.webp"},"画面":"十月头场雪，芦雪广屋里围着火盆，众人刚联完诗。李纨坐在上首，笑着指宝玉罚他；宝玉起身答应，湘云、黛玉在旁说外头冷。窗外大雪。","quote":{"文":"可厭妙玉為人，我不理他。如今罰你去取一枝來。","回":50}},"pinchamei:6":{"n":"栊翠庵品茶与乞梅·第6幅","t":"芦雪广","册":"pinchamei","幅":6,"line":"「一語未了，只見寶玉笑嘻嘻的掮了一枝紅梅進來，眾丫鬟忙已接過，插入瓶內。」“掮”是扛在肩上。他一进门就说：你们赏罢，不知费了我多少精神。一身蓑笠一肩梅，雪里这一幅已胜过诗。同一回里宝琴立在雪坡上，众人说她像「仇十洲畫的《雙艷圖》」。","place":"luxue","hui":[50],"img":{"full":"dgy-assets/huace/img/pinchamei-06.webp","thumb":"dgy-assets/huace/img/pinchamei-06-s.webp"},"画面":"雪天，芦雪广门口，宝玉披蓑戴笠，肩上扛着一枝二尺来高、横枝五六尺长的红梅，笑嘻嘻进门；丫鬟们接过梅花插进美女耸肩瓶，又上前替他接蓑笠、掸雪。","quote":{"文":"一語未了，只見寶玉笑嘻嘻的掮了一枝紅梅進來，眾丫鬟忙已接過，插入瓶內。","回":50}},"lianju:1":{"n":"凹晶馆联诗·第1幅","t":"凹晶溪馆","册":"lianju","幅":1,"line":"「因這幾間就在此山懷抱之中，乃凸碧山莊之退居，因窪而近水，故顏其額曰「凹晶溪館」。」山顶叫“凸碧”，水边叫“凹晶”，一高一低正好一对——这两个名字是黛玉拟的。园子盖好几年，凸碧凹晶的来历，到今夜才由黛玉说出来，「凡我擬的，一字不改都用了」。","place":"aojing","hui":[76],"img":{"full":"dgy-assets/huace/img/lianju-01.webp","thumb":"dgy-assets/huace/img/lianju-01-s.webp"},"画面":"中秋夜，月光下，黛玉、湘云两人携手从山坡下来，一转弯就是池沿，一带竹栏相接；水边几间矮小的房子，门额上写“凹晶溪馆”，灯已熄了。","quote":{"文":"因這幾間就在此山懷抱之中，乃凸碧山莊之退居，因窪而近水，故顏其額曰「凹晶溪館」。","回":76}},"lianju:2":{"n":"凹晶馆联诗·第2幅","t":"凹晶溪馆","册":"lianju","幅":2,"line":"「二人遂在兩個湘妃竹墩上坐下。只見天上一輪皓月，池中一輪水月，上下爭輝，如置身於晶宮鮫室之內。」宴席上人散得冷清，两人干脆躲到这里联句。天上一轮，水里一轮，竹墩上坐着两个没爹娘的姑娘。中秋团圆夜，团圆的只有月亮。","place":"aojing","hui":[76],"img":{"full":"dgy-assets/huace/img/lianju-02.webp","thumb":"dgy-assets/huace/img/lianju-02-s.webp"},"画面":"凹晶溪馆前水边，两只湘妃竹墩，黛玉、湘云并肩坐着；天上一轮满月，池里一轮倒影，四下清冷如水晶宫。","quote":{"文":"二人遂在兩個湘妃竹墩上坐下。只見天上一輪皓月，池中一輪水月，上下爭輝，如置身於晶宮鮫室之內。","回":76}},"lianju:3":{"n":"凹晶馆联诗·第3幅","t":"凹晶溪馆","册":"lianju","幅":3,"line":"「只聽那黑影裡嘎然一聲，卻飛起一個大白鶴來，直往藕香榭去了。黛玉笑道：「原來是他，猛然想不到，反嚇了一跳。」」黛玉以为池里黑影是鬼，湘云说她不怕鬼，拾石片一打，打出一只鹤来。黛玉疑是鬼，湘云偏去打。一块石片打出来的，竟是下一句诗。","place":"aojing","hui":[76],"img":{"full":"dgy-assets/huace/img/lianju-03.webp","thumb":"dgy-assets/huace/img/lianju-03-s.webp"},"画面":"湘云弯腰向池中扔出一块小石片，水面月影荡开；池中黑影里一只大白鹤惊起，振翅朝远处水榭飞去；黛玉在竹栏边吓了一跳，随即笑了。","quote":{"文":"只聽那黑影裡嘎然一聲，卻飛起一個大白鶴來，直往藕香榭去了。黛玉笑道：「原來是他，猛然想不到，反嚇了一跳。」","回":76}},"lianju:4":{"n":"凹晶馆联诗·第4幅","t":"凹晶溪馆","册":"lianju","幅":4,"line":"「黛玉只看天，不理他，半日，猛然笑道：「你不必說嘴，我也有了，你聽聽。」因對道：冷月葬花魂。」湘云上句是“寒塘渡鹤影”，黛玉对“冷月葬花魂”。湘云叫好，又劝她病中别作这样太颓丧的句子。鹤影归湘云，花魂归黛玉，一联里两个人的下场都分派好了。月影打散还能复聚，人散了不聚。","place":"aojing","hui":[76],"img":{"full":"dgy-assets/huace/img/lianju-04.webp","thumb":"dgy-assets/huace/img/lianju-04-s.webp"},"画面":"湘云刚借白鹤对出一句，得意地看着黛玉；黛玉仰头望着冷月不理她，半晌忽然一笑开口；水面月影碎银般闪动。","quote":{"文":"黛玉只看天，不理他，半日，猛然笑道：「你不必說嘴，我也有了，你聽聽。」因對道：冷月葬花魂。","回":76}},"lianju:5":{"n":"凹晶馆联诗·第5幅","t":"凹晶溪馆","册":"lianju","幅":5,"line":"「一語未了，只見欄外山石後轉出一個人來，笑道：「好詩，好詩，果然太悲涼了。不必再往下聯，若底下只這樣去，反不顯這兩句了，倒覺得堆砌牽強。」」她赏月走到这里，在石后听了半天，嫌太悲凉，出来止住。躲在石后听诗的，又是一个孤零零的人。三个人凑成的中秋，倒比山上的家宴更像一家。","place":"aojing","hui":[76],"img":{"full":"dgy-assets/huace/img/lianju-05.webp","thumb":"dgy-assets/huace/img/lianju-05-s.webp"},"画面":"竹栏外假山石后转出一个人：妙玉，月白衣衫，手执拂尘，含笑说话；黛玉、湘云回头，一脸惊诧。","quote":{"文":"一語未了，只見欄外山石後轉出一個人來，笑道：「好詩，好詩，果然太悲涼了。不必再往下聯，若底下只這樣去，反不顯這兩句了，倒覺得堆砌牽強。」","回":76}},"lianju:6":{"n":"凹晶馆联诗·第6幅","t":"栊翠庵","册":"lianju","幅":6,"line":"「我意思想著你二位警句已出，再若續時，恐後力不加。我竟要續貂，又恐有玷。」她说两人已联了二十二韵，警句已出，由她来收尾。黛玉从没见她作过诗。她说收结「還該歸到本來面目上去」，硬把悲音挽了回来。挽回了诗，挽不回人。山下两人联句，庵中一人收尾；夜深时有纸笔相接，清晨各自散去，这一席知音只留在写成的篇章里。","place":"longcui","hui":[76],"img":{"full":"dgy-assets/huace/img/lianju-06.webp","thumb":"dgy-assets/huace/img/lianju-06-s.webp"},"画面":"栊翠庵禅房，夜将尽，佛龛灯焰青青、炉香未尽，小丫鬟在蒲团上打盹。妙玉坐在案前取纸笔把两人的诗从头写出，黛玉、湘云在旁看着，神情惊喜。","quote":{"文":"我意思想著你二位警句已出，再若續時，恐後力不加。我竟要續貂，又恐有玷。","回":76}},"aida:1":{"n":"宝玉挨打·第1幅","t":"王夫人上房","册":"aida","幅":1,"line":"金钏投了井，王夫人在里间垂泪，宝钗把自己的两套新衣送来给她妆裹。宝玉坐在一旁也垂着泪，见宝钗进来，王夫人便掩了口。这一回的祸，是从一屋子说不出口的话起的。一件衣裳送来，暂可料理身后事，却不能使活着的人把金钏之死说得明白。","place":null,"hui":[32],"img":{"full":"dgy-assets/huace/img/aida-01.webp","thumb":"dgy-assets/huace/img/aida-01-s.webp"},"画面":"盛夏白天，王夫人上房里间，鸦雀无闻。王夫人湘黄缎褙子，坐在炕边拭泪，见宝钗捧着两套衣裳进门，忙掩了口；宝玉橘红短褂，坐在一旁垂泪，低头不语。窗外日光白亮。中景。","quote":{"文":"一時寶釵取了衣服回來，只見寶玉在王夫人旁邊坐著垂淚。王夫人正才說他，因寶釵來了，卻掩了口不說了。","回":32}},"aida:2":{"n":"宝玉挨打·第2幅","t":"厅上屏门","册":"aida","幅":2,"line":"他背着手低头，一面感叹一面慢走，刚转过屏门，正撞在父亲怀里。贾政问他为何垂头丧气，他一心只在金钏身上，只怔呵呵的站着。父子之间，最怕的就是这一怔。屏门原只隔着两处屋子，宝玉这一撞，却从私下的悲意撞进了父亲的盘问。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-02.webp","thumb":"dgy-assets/huace/img/aida-02-s.webp"},"画面":"厅上屏门转角，宝玉背着手低头慢走，满脸失魂落魄；迎面贾政浅灰蓝袍、黄扁小冠正往里走，两人撞个满怀。贾政喝住，宝玉抬头倒抽一口气，垂手退到一旁。中近景，屏门作框。","quote":{"文":"背著手，低頭一面感歎，一面慢慢的走著，信步來至廳上。剛轉過屏門，不想對面來了一人正往裡走，可巧兒撞了個滿懷。","回":33}},"aida:3":{"n":"宝玉挨打·第3幅","t":"厅上","册":"aida","幅":3,"line":"素不往来的忠顺府忽然打发长史官来，坐下便冷笑着要人。王府唱小旦的琪官三五日不见，满城都说他和「銜玉的那位令郎相與甚厚」。贾政又惊又气，这把火先从外头点起来了。家中父子之争尚未开口，王府先来索人；门第之下的公子，原也有自己不敢应的外头权势。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-03.webp","thumb":"dgy-assets/huace/img/aida-03-s.webp"},"画面":"厅上，忠顺府长史官官服端坐客位，手扶茶盏，嘴角冷笑；贾政浅灰蓝袍，赔笑起身拱手，脸色由疑转惊。门外两个小厮垂手侍立。中景，长史官居画面偏左，茶盏冒着热气。","quote":{"文":"我們府里有一個做小旦的琪官，一向好好在府里，如今竟三五日不見回去，各處去找，又摸不著他的道路，因此各處訪察。這一城內，十停人倒有八停人都說，他近日和銜玉的那位令郎相與甚厚。","回":33}},"aida:4":{"n":"宝玉挨打·第4幅","t":"厅上","册":"aida","幅":4,"line":"宝玉连说不知琪官为何物，长史官只冷笑问一句，那红汗巾子怎么到了公子腰里。他登时轰去魂魄，只得说出紫檀堡来打发人走。一条汗巾，比十句分辩都重。一个贴身物件突然变成证据，宝玉从含混抵赖到不得不认，局面便再也不由他掌握。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-04.webp","thumb":"dgy-assets/huace/img/aida-04-s.webp"},"画面":"宝玉被叫到厅上，站在贾政面前哭着分辩；长史官冷笑着抬手指向宝玉腰间。宝玉一怔，目瞪口呆，手不由自主按住腰带。贾政气得胡须发抖。中景，三人成三角，宝玉居中。","quote":{"文":"既雲不知此人，那紅汗巾子怎麼到了公子腰裡？」","回":33}},"aida:5":{"n":"宝玉挨打·第5幅","t":"厅上","册":"aida","幅":5,"line":"长史官前脚走，贾环后脚撞上来，先说井里淹死了丫头，再扯住袍襟贴膝跪下。回头四顾一看，才悄悄说出「拉著太太的丫頭金釧兒強奸不遂」。回目叫「小動唇舌」，唇舌虽小，板子却大。前一桩传闻尚未平息，后一桩诬告又至，贾政把两事并在一处，怒气便无从分辨。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-05.webp","thumb":"dgy-assets/huace/img/aida-05-s.webp"},"画面":"贾政送客回身，满面怒容；贾环扯住他的袍襟贴膝跪下，回头四顾，凑近压低嗓子说话。几个小厮会意，往两边后面退去。贾环少年常服，色暗于宝玉，神情鬼祟。中景，贾环在前景。","quote":{"文":"賈環忙上前拉住賈政的袍襟，貼膝跪下道：「父親不用生氣。此事除太太房裡的人，別人一點也不知道。我聽見我母親說……」說到這里，便回頭四顧一看。","回":33}},"aida:6":{"n":"宝玉挨打·第6幅","t":"书房","册":"aida","幅":6,"line":"贾政气得面如金纸，坐在椅子上一叠声喝「拿寶玉！拿大棍！拿索子捆上」。门客们啖指咬舌，连忙退出。做父亲的满面泪痕下令打儿子，可知这一棍先打在他自己心上。他有悲意，却更有把家法与官场羞辱混在一处的惊惧；父亲的泪也没有挡住刑杖。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-06.webp","thumb":"dgy-assets/huace/img/aida-06-s.webp"},"画面":"书房里，贾政直挺挺坐在椅上，喘吁吁满面泪痕，一手拍着扶手连声喝令；门客们咬指吐舌，纷纷退出门外；几个小厮应声往外跑。门窗外夏日刺眼。中景，贾政居中，众人向外散。","quote":{"文":"那賈政喘吁吁直挺挺坐在椅子上，滿面淚痕，一疊聲「拿寶玉！拿大棍！拿索子捆上！把各門都關上！有人傳信往裡頭去，立刻打死！」","回":33}},"aida:7":{"n":"宝玉挨打·第7幅","t":"厅上","册":"aida","幅":7,"line":"偏生焙茗不在，好容易撞见一个老姆姆，宝玉拉住她说「要緊，要緊」，她偏听作了跳井。还笑他「跳井讓他跳去，二爺怕什麼」。可笑处正是可怕处，金钏的死在府里已成了一句闲话。传话的路被一场误听堵死，园中惯有的机灵小厮此刻偏偏不在，竟无人能先替他报信。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-07.webp","thumb":"dgy-assets/huace/img/aida-07-s.webp"},"画面":"厅上，宝玉急得跺脚，一把拉住一个白发老姆姆的衣袖，凑在她耳边大声说话；老姆姆侧着耳朵，满脸笑意，摆手不以为然。四下再无别人，廊外日光白亮。中近景，一急一笑。","quote":{"文":"寶玉一則急了，說話不明白，二則老婆子偏生又聾，竟不曾聽見是什麼話，把「要緊」二字只聽作「跳井」二字，便笑道：「跳井讓他跳去，二爺怕什麼？」","回":33}},"aida:8":{"n":"宝玉挨打·第8幅","t":"书房","册":"aida","幅":8,"line":"小厮们打了十来下，贾政还嫌轻，一脚踢开掌板的，自己夺过来咬着牙狠命盖了三四十下。门客们上前夺劝，反被他一句「釀到他弒君殺父」顶了回去。打的是儿子，恨的是这些年没管住的一切。众人要夺棍而不得，书房中有主仆、有父子，却没有一个人能叫这一场停下来。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-08.webp","thumb":"dgy-assets/huace/img/aida-08-s.webp"},"画面":"书房里，宝玉被按在长凳上，嘴已堵住；贾政一脚踢开掌板的小厮，自己夺过大板，咬牙高高举起，浅灰蓝袍下摆飞起。门客们上前要拦又不敢。中景，动势强烈，色调压暗。","quote":{"文":"小廝們不敢違拗，只得將寶玉按在凳上，舉起大板打了十來下。賈政猶嫌打輕了，一腳踢開掌板的，自己奪過來，咬著牙狠命蓋了三四十下。","回":33}},"aida:9":{"n":"宝玉挨打·第9幅","t":"书房","册":"aida","幅":9,"line":"王夫人顾不得有人没人，赶进书房一把抱住板子。她说「寶玉雖然該打，老爺也要自重」，又说炎天暑日，老太太身上不好。这是这一回里头一句软话，可惜软话总来迟一步。王夫人抱的虽是板子，口里求的却是贾政记起自己也身在这个家中。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-09.webp","thumb":"dgy-assets/huace/img/aida-09-s.webp"},"画面":"王夫人湘黄褙子，鬓发微乱，冲进书房死死抱住贾政手里的板子，满脸是泪；按人的两个小厮已松手退开，宝玉趴在凳上动弹不得。贾政举板的手僵在半空。近景，三人纠在一处。","quote":{"文":"賈政還欲打時，早被王夫人抱住板子。賈政道：「罷了，罷了！今日必定要氣死我才罷！」王夫人哭道：「寶玉雖然該打，老爺也要自重。況且炎天暑日的，老太太身上也不大好，打死寶玉事小，倘或老太太一時不自在了，豈不事大！」","回":33}},"aida:10":{"n":"宝玉挨打·第10幅","t":"书房","册":"aida","幅":10,"line":"绿纱小衣上全是血渍，由臀至胫，竟无一点好处。王夫人哭出一声苦命儿，忽又想起贾珠，叫着贾珠的名字哭。别人还可，惟有李纨放声哭了，她哭的是自己早死的丈夫。一句贾珠，把此刻的伤牵到多年旧痛；李纨的哭声，便与满屋人的哭声有了不同来处。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-10.webp","thumb":"dgy-assets/huace/img/aida-10-s.webp"},"画面":"王夫人伏在凳边抱着宝玉，宝玉面白气弱，下身一条绿纱小衣浸满血渍；王夫人解下汗巾看伤，失声大哭。身后李纨天蓝褙子、凤姐大红窄袄、迎春姊妹赶进门来，李纨以帕掩面。中景。","quote":{"文":"王夫人抱著寶玉，只見他面白氣弱，底下穿著一條綠紗小衣皆是血漬，禁不住解下汗巾看，由臀至脛，或青或紫，或整或破，竟無一點好處，不覺失聲大哭起來，「苦命的兒嚇！」","回":33}},"aida:11":{"n":"宝玉挨打·第11幅","t":"书房窗外","册":"aida","幅":11,"line":"一句话未了，窗外颤巍巍一声「先打死我，再打死他，豈不乾淨了」。贾政连忙迎出来，躬身陪笑说大暑热天何必亲自走来。满屋人劝不住的，老祖宗一句话便劝住了。贾母并未入屋便先夺了声势，辈分和母子情都在窗外这一声里压过了家法。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-11.webp","thumb":"dgy-assets/huace/img/aida-11-s.webp"},"画面":"书房窗外廊下，贾母银灰蓝宽袖褂、满头银发，扶着丫鬟喘吁吁颤巍巍赶来，满脸怒容；贾政慌忙迎出门，躬身陪笑。门内隐约是哭成一团的众人。中景，贾母居高，贾政躬身在低处。","quote":{"文":"一句話未了，只聽窗外顫巍巍的聲氣說道：「先打死我，再打死他，豈不乾淨了！」","回":33}},"aida:12":{"n":"宝玉挨打·第12幅","t":"书房外","册":"aida","幅":12,"line":"贾政跪下说教训儿子为光宗耀祖，贾母啐他一口，「當初你父親怎麼教訓你來」。说着便要看轿马回南京去，贾政只得苦苦叩求认罪。一家之主跪在地上，这是贾府最大的一条规矩。方才挥棍的人如今叩头认错，宝玉仍躺在里面；家中权力转了一圈，伤却已落在身上。","place":null,"hui":[33],"img":{"full":"dgy-assets/huace/img/aida-12.webp","thumb":"dgy-assets/huace/img/aida-12-s.webp"},"画面":"贾政跪在贾母面前含泪叩头，贾母扶着丫鬟立着，一面落泪一面厉声说话；后面凤姐大红窄袄，指着媳妇们抬出藤屉春凳，众人七手八脚把宝玉抬上去。中景，前跪后忙。","quote":{"文":"賈母聽說，便啐了一口，說道：「我說一句話，你就禁不起，你那樣下死手的板子，難道寶玉就禁得起了？你說教訓兒子是光宗耀祖，當初你父親怎麼教訓你來！」","回":33}},"aida:13":{"n":"宝玉挨打·第13幅","t":"怡红院","册":"aida","幅":13,"line":"宝钗托着一丸药进来，嘱咐用酒研开敷上。说到「早聽人一句話，也不至今日」，又忙咽住，红了脸低下头去。话只说了半句，宝玉倒把疼痛丢在了九霄云外。药是实在的照料，话却说到半截；宝钗平日的稳重，也在这半句里露出难以遮掩的关切。","place":"yihong","hui":[34],"img":{"full":"dgy-assets/huace/img/aida-13.webp","thumb":"dgy-assets/huace/img/aida-13-s.webp"},"画面":"怡红院卧房，宝玉趴卧床上，身上盖一床袷纱被；宝钗粉紫织金交领衫，手心托着一丸药立在床前说话，说到半句忽然红了脸，低头摆弄衣带；袭人玫粉袄在旁伸手接药。近景，药丸为焦点。","quote":{"文":"只見寶釵手裡托著一丸藥走進來，向襲人說道：「晚上把這藥用酒研開，替他敷上，把那淤血的熱毒散開，可以就好了。」","回":34}},"aida:14":{"n":"宝玉挨打·第14幅","t":"怡红院","册":"aida","幅":14,"line":"宝玉醒来，见她两个眼睛肿得桃儿一般，还哄她说是装出来的。她心中虽有万句言语，半日只抽噎出一句「你從此可都改了罷」。他答就便为这些人死了也是情愿，一劝一答，两个人的路都定了。宝钗劝他听话，黛玉劝他改过，字面相近，心里各有疼法；宝玉却仍把自己的那条路说定了。","place":"yihong","hui":[34],"img":{"full":"dgy-assets/huace/img/aida-14.webp","thumb":"dgy-assets/huace/img/aida-14-s.webp"},"画面":"太阳刚落，怡红院床前。黛玉淡紫立领袄，坐在床沿，两眼肿得桃儿一般，满面泪光，抽抽噎噎；宝玉欠起半身细细认她，又疼得倒下。屋角通后院的小门虚掩。近景，暮色偏暖。","quote":{"文":"寶玉猶恐是夢，忙又將身子欠起來，向臉上細細一認，只見兩個眼睛腫的桃兒一般，滿面淚光，不是黛玉，卻是那個？","回":34}},"zhengmen:1":{"n":"正门初入·第1幅","t":"正门","册":"zhengmen","幅":1,"line":"「賈政道：「你且把園門都關上，我們先瞧了外面再進去。」賈珍聽說，命人將門關了。」题匾之前，先把园门关上，从外面看一遍。宝玉原是一溜烟要出园的，顶头撞上，「躲之不及」，只得一边站了。一园的匾额，都从这一躲不及里来。贾政本来要带清客细看新园，临时把儿子留在身边；日后许多园中名字，就在这场不期而遇的试才里定下。","place":"gate","hui":[17],"img":{"full":"dgy-assets/huace/img/zhengmen-01.webp","thumb":"dgy-assets/huace/img/zhengmen-01-s.webp"},"画面":"白天，园门外的空场。贾政立在台阶前，抬手吩咐；贾珍侧身恭立听令；几个仆人把五开间的大门扇合上。宝玉带着奶娘小厮站在贾政身后侧，垂手低头（中景侧身，不要求认脸）。门前没有人喧哗。","quote":{"文":"賈政道：「你且把園門都關上，我們先瞧了外面再進去。」賈珍聽說，命人將門關了。","回":17}},"zhengmen:2":{"n":"正门初入·第2幅","t":"正门","册":"zhengmen","幅":2,"line":"「只見正門五間，上面桶瓦泥鰍脊，那門欄窗槅，皆是細雕新鮮花樣，並無朱粉塗飾，一色水磨群牆，下面白石臺磯，鑿成西番草花樣。」大门不走朱门金钉那一路：细雕，不涂朱粉，台基上凿的是西番草花。细雕而不施彩，钱都花在看不见的刀工上。富贵人家最贵的一种俭省，便是这扇门。","place":"gate","hui":[17],"img":{"full":"dgy-assets/huace/img/zhengmen-02.webp","thumb":"dgy-assets/huace/img/zhengmen-02-s.webp"},"画面":"正门五间近景：桶瓦泥鳅脊的屋顶；门框窗槅细雕新鲜花样，不涂朱红；粉墙水磨砖，下面白石台基，凿出西番草花样。台阶前没有人。","quote":{"文":"只見正門五間，上面桶瓦泥鰍脊，那門欄窗槅，皆是細雕新鮮花樣，並無朱粉塗飾，一色水磨群牆，下面白石臺磯，鑿成西番草花樣。","回":17}},"zhengmen:3":{"n":"正门初入·第3幅","t":"正门","册":"zhengmen","幅":3,"line":"「左右一望，皆雪白粉牆，下面虎皮石，隨勢砌去，果然不落富麗俗套，自是歡喜。」他欢喜的是不落富丽俗套。贾政这一喜，喜在不俗。他一路骂宝玉，也是怕俗；偏生宝玉题的，处处比清客们不俗。雪墙与虎皮石随着地势延伸，门外尚看不见园中胜景，先让人认出主人家不肯堆砌富丽的眼光。","place":"gate","hui":[17],"img":{"full":"dgy-assets/huace/img/zhengmen-03.webp","thumb":"dgy-assets/huace/img/zhengmen-03-s.webp"},"画面":"贾政站在台阶上左右看：雪白粉墙，下面砌着虎皮石，随着地势砌去。他微微点头，神色放松；贾珍和清客在后面等着。","quote":{"文":"左右一望，皆雪白粉牆，下面虎皮石，隨勢砌去，果然不落富麗俗套，自是歡喜。","回":17}},"zhengmen:4":{"n":"正门初入·第4幅","t":"正门","册":"zhengmen","幅":4,"line":"「遂命開門，只見迎面一帶翠嶂擋在前面。」门一开先看见山，看不见园子。山的细部在「曲径通幽」册。门开了，园子还藏着，头一眼只给一座山。好比这部书开卷，先不说人，先说一块石头。行人须绕过它，才看得见后面的花木与清流；这一遮一露，也替接下来的题额和行路定了步调。","place":"gate","hui":[17],"img":{"full":"dgy-assets/huace/img/zhengmen-04.webp","thumb":"dgy-assets/huace/img/zhengmen-04-s.webp"},"画面":"大门打开了。画面从门外看进去：门洞里迎面一座翠嶂，挡住了园里的景。贾政、宝玉和清客的背影立在门槛前（背影，不画玉）。","quote":{"文":"遂命開門，只見迎面一帶翠嶂擋在前面。","回":17}},"gexing:1":{"n":"芦雪广割腥啖膻·第1幅","t":"芦雪广","册":"gexing","幅":1,"line":"「原來這蘆雪庵蓋在傍山臨水河灘之上，一帶幾間，茅檐土壁，槿籬竹牖，推窗便可垂釣，四面都是蘆葦掩覆，一條去徑逶迤穿蘆度葦過去，便是藕香榭的竹橋了。」头一天李纨说稻香村不如这里，已经让人笼了地炕。联句和烤鹿肉都在这几间屋里和屋外。茅檐土壁，四面芦苇，是园里最荒的一处。这一冬最热闹的一场，偏摆在这里。","place":"luxue","hui":[49],"img":{"full":"dgy-assets/huace/img/gexing-01.webp","thumb":"dgy-assets/huace/img/gexing-01-s.webp"},"画面":"雪后清晨。傍山临水的河滩上，一带茅檐土壁的小屋，屋顶压着厚雪；槿篱竹窗；丫鬟婆子正在扫雪开径；一条小路穿过白头芦苇，通向远处的竹桥。窗外是水面。","quote":{"文":"原來這蘆雪庵蓋在傍山臨水河灘之上，一帶幾間，茅檐土壁，槿籬竹牖，推窗便可垂釣，四面都是蘆葦掩覆，一條去徑逶迤穿蘆度葦過去，便是藕香榭的竹橋了。","回":49}},"gexing:2":{"n":"芦雪广割腥啖膻·第2幅","t":"芦雪广","册":"gexing","幅":2,"line":"「李紈等忙出來找著他兩個說道：「你們兩個要吃生的，我送你們到老太太那裡吃去。那怕吃一隻生鹿，撐病了不與我相干。這麼大雪，怪冷的，替我作禍呢。」寶玉笑道：「沒有的事，我們燒著吃呢。」李紈道：「這還罷了。」只見老婆們拿了鐵爐，鐵叉，鐵絲幪來，李紈道：「仔細割了手，不許哭！」」李婶看见他们商量着要吃生肉，说给了众人，李纨才出来找。湘云在贾母房里吃饭时就悄悄和宝玉说好，要一块鹿肉来园里“又顽又吃”。李纨嘴上撵他们去老太太那里吃，铁炉铁叉倒先送了来。这位寡嫂的管，是带着疼的管。","place":"luxue","hui":[49],"img":{"full":"dgy-assets/huace/img/gexing-02.webp","thumb":"dgy-assets/huace/img/gexing-02-s.webp"},"画面":"雪地里，李纨站在檐下，一手指着宝玉和湘云教训；老婆子抱着铁炉、铁叉、铁丝蒙走来；宝玉笑着摆手解释，湘云在他旁边抿嘴笑。","quote":{"文":"李紈等忙出來找著他兩個說道：「你們兩個要吃生的，我送你們到老太太那裡吃去。那怕吃一隻生鹿，撐病了不與我相干。這麼大雪，怪冷的，替我作禍呢。」寶玉笑道：「沒有的事，我們燒著吃呢。」李紈道：「這還罷了。」只見老婆們拿了鐵爐，鐵叉，鐵絲幪來，李紈道：「仔細割了手，不許哭！」","回":49}},"gexing:3":{"n":"芦雪广割腥啖膻·第3幅","t":"芦雪广","册":"gexing","幅":3,"line":"「湘雲一面吃，一面說道：「我吃這個方愛吃酒，吃了酒才有詩。若不是這鹿肉，今兒斷不能作詩。」」平儿那只镯子吃完才发现丢了，凤姐说“不出三日包管就有”。湘云的道理是：吃了鹿肉才爱吃酒，吃了酒才有诗。平儿褪镯子最不经意。那只虾须镯，后来查出是怡红院的坠儿拿的，晴雯病中撵了她（第52回）。","place":"luxue","hui":[49],"img":{"full":"dgy-assets/huace/img/gexing-03.webp","thumb":"dgy-assets/huace/img/gexing-03-s.webp"},"画面":"雪地里生着铁炉，宝玉蹲着用铁叉烤肉，湘云一手拿着烤好的肉，边吃边说话；平儿挽着袖子蹲在炉边，褪下的镯子放在一旁石头上。远处宝琴披着凫靥裘笑着站着看，宝钗黛玉并肩立在后面，侧身，不要求认脸。","quote":{"文":"湘雲一面吃，一面說道：「我吃這個方愛吃酒，吃了酒才有詩。若不是這鹿肉，今兒斷不能作詩。」","回":49}},"gexing:4":{"n":"芦雪广割腥啖膻·第4幅","t":"芦雪广","册":"gexing","幅":4,"line":"「黛玉笑道：「那裡找這一群花子去！罷了，罷了，今日蘆雪庵遭劫，生生被雲丫頭作踐了。我為蘆雪庵一大哭！」湘雲冷笑道：「你知道什麼！『是真名士自風流』，你們都是假清高，最可厭的。我們這會子腥膻大吃大嚼，回來卻是錦心繡口。」寶釵笑道：「你回來若作的不好了，把那肉掏了出來，就把這雪壓的蘆葦子揌上些，以完此劫。」」宝钗的意思是：你要是作不好，就把肉掏出来，塞进被雪压着的芦苇里，算了结这场劫。黛玉骂花子，湘云回真名士，宝钗这一句最毒也最好笑：诗作不好，连吃下去的肉都要退回来。","place":"luxue","hui":[49],"img":{"full":"dgy-assets/huace/img/gexing-04.webp","thumb":"dgy-assets/huace/img/gexing-04-s.webp"},"画面":"凤姐披着斗篷走来，凑在炉边也吃，背影，不要求认脸；黛玉笑着用手帕掩口、手指湘云，湘云冷笑着抬下巴；宝钗抿嘴笑。","quote":{"文":"黛玉笑道：「那裡找這一群花子去！罷了，罷了，今日蘆雪庵遭劫，生生被雲丫頭作踐了。我為蘆雪庵一大哭！」湘雲冷笑道：「你知道什麼！『是真名士自風流』，你們都是假清高，最可厭的。我們這會子腥膻大吃大嚼，回來卻是錦心繡口。」寶釵笑道：「你回來若作的不好了，把那肉掏了出來，就把這雪壓的蘆葦子揌上些，以完此劫。」","回":49}},"gexing:5":{"n":"芦雪广割腥啖膻·第5幅","t":"芦雪广","册":"gexing","幅":5,"line":"「湘雲伏著已笑軟了。眾人看他三人對搶，也都不顧作詩，看著也只是笑。黛玉還推他往下聯，又道：「你也有才盡之時。我聽聽還有什麼舌根嚼了！」湘雲只伏在寶釵懷裡，笑個不住。寶釵推他起來道：「你有本事，把『二蕭』的韻全用完了，我才伏你。」湘雲起身笑道：「我也不是作詩，竟是搶命呢。」」题目是「即景联句，五言排律一首，限二萧韵」，贴在墙上。湘云自己说“不是作诗，竟是抢命”。这一冬湘云执意要和宝钗一处住（第49回）。抢命抢到末了，还是往宝姐姐怀里一伏。","place":"luxue","hui":[50],"img":{"full":"dgy-assets/huace/img/gexing-05.webp","thumb":"dgy-assets/huace/img/gexing-05-s.webp"},"画面":"地炕屋里，墙上贴着一张空白的题纸条，杯盘果菜已摆齐。湘云笑得伏在宝钗怀里，站不直；黛玉伸手推她往下联。","quote":{"文":"湘雲伏著已笑軟了。眾人看他三人對搶，也都不顧作詩，看著也只是笑。黛玉還推他往下聯，又道：「你也有才盡之時。我聽聽還有什麼舌根嚼了！」湘雲只伏在寶釵懷裡，笑個不住。寶釵推他起來道：「你有本事，把『二蕭』的韻全用完了，我才伏你。」湘雲起身笑道：「我也不是作詩，竟是搶命呢。」","回":50}},"zhouru:1":{"n":"舟入花溆·第1幅","t":"蓼汀花溆","册":"zhouru","幅":1,"line":"「忽又見執拂太監跪請登舟，賈妃乃下輿。只見清流一帶，勢如游龍，兩邊石欄上，皆係水晶玻璃各色風燈，點的如銀花雪浪」这是进石港之前的水面，下一幅才进港。灯火到这里，作者反收了笔，说恐「入了別書的俗套」。写得最省的，正是最阔的一夜。","place":"huaxu","hui":[18],"img":{"full":"dgy-assets/huace/img/zhouru-01.webp","thumb":"dgy-assets/huace/img/zhouru-01-s.webp"},"画面":"夜里，元春下轿登舟，凤冠、明黄；两岸石栏上挂着水晶玻璃风灯，亮得如银花雪浪；船在一带清流上缓行。","quote":{"文":"忽又見執拂太監跪請登舟，賈妃乃下輿。只見清流一帶，勢如游龍，兩邊石欄上，皆係水晶玻璃各色風燈，點的如銀花雪浪","回":18}},"zhouru:2":{"n":"舟入花溆·第2幅","t":"蓼汀花溆","册":"zhouru","幅":2,"line":"「上面柳杏諸樹雖無花葉，然皆用通草綢綾紙絹依勢作成，粘於枝上的，每一株懸燈數盞，更兼池中荷荇鳧鷺之屬，亦皆係螺蚌羽毛之類作就的。」假花是这一夜的灯饰，不是树本身开了花。元宵时节柳杏无花，就拿绸绢粘上去。这园子头一回见贵人，满树开的是假花。","place":"huaxu","hui":[18],"img":{"full":"dgy-assets/huace/img/zhouru-02.webp","thumb":"dgy-assets/huace/img/zhouru-02-s.webp"},"画面":"岸上柳树、杏树没有花叶，枝上用通草、绸绫、纸绢做成假花假叶，每株挂灯数盏；池中荷荇凫鹭是螺蚌羽毛做的，在灯光里闪着光。","quote":{"文":"上面柳杏諸樹雖無花葉，然皆用通草綢綾紙絹依勢作成，粘於枝上的，每一株懸燈數盞，更兼池中荷荇鳧鷺之屬，亦皆係螺蚌羽毛之類作就的。","回":18}},"zhouru:3":{"n":"舟入花溆·第3幅","t":"蓼汀花溆","册":"zhouru","幅":3,"line":"「已而入一石港，港上一面匾燈，明現著「蓼汀花漵」四字。」这四个字是第十七回宝玉题的。试才那天贾政批它胡说，今夜还是做成匾灯挂在港口。宝玉三四岁时的书，原是元春「手引口傳」教的。船从匾下过，姐姐先看见弟弟留下的字；隔着宫中礼数，这一笔家常仍有地方落脚。","place":"huaxu","hui":[18],"img":{"full":"dgy-assets/huace/img/zhouru-03.webp","thumb":"dgy-assets/huace/img/zhouru-03-s.webp"},"画面":"船进一座石港。港口上方悬着一面匾灯，灯面空白（不画字）；萝薜倒垂在洞口，灯影落水。","quote":{"文":"已而入一石港，港上一面匾燈，明現著「蓼汀花漵」四字。","回":18}},"zhouru:4":{"n":"舟入花溆·第4幅","t":"蓼汀花溆","册":"zhouru","幅":4,"line":"「賈妃看了四字，笑道：「『花漵』二字便妥，何必，『蓼汀』？」侍座太監聽了，忙下小舟登岸，飛傳與賈政。賈政聽了，即忙移換。」元春只要「花漵」两个字，不要「蓼汀」。底本这句「何必」后面有逗号，照抄。换完匾，船才驶向内岸的省亲别墅。删两个字，太监便下船飞传，一家子半夜换匾。省亲的规矩，连一句笑谈也是旨意。","place":"huaxu","hui":[18],"img":{"full":"dgy-assets/huace/img/zhouru-04.webp","thumb":"dgy-assets/huace/img/zhouru-04-s.webp"},"画面":"船舱里，元春看着匾灯，抬手说话；太监躬身，随即下到一条小舟划向岸边传话；岸上贾政忙叫人换匾。","quote":{"文":"賈妃看了四字，笑道：「『花漵』二字便妥，何必，『蓼汀』？」侍座太監聽了，忙下小舟登岸，飛傳與賈政。賈政聽了，即忙移換。","回":18}},"zhouru:5":{"n":"舟入花溆·第5幅","t":"蓼汀花溆","册":"zhouru","幅":5,"line":"「林黛玉道：「我最不喜歡李義山的詩，只喜他這一句：『留得殘荷聽雨聲』。偏你們又不留著殘荷了。」寶玉道：「果然好句，以後咱們就別叫人拔去了。」說著已到了花漵的蘿港之下，覺得陰森透骨，兩灘上衰草殘菱，更助秋情。」黛玉要留着残荷听雨声，宝玉说以后就别叫人拔了。船随后在蘅芜苑前靠岸。省亲那夜，这池里是羽毛扎的荷，灯照得通明；如今真荷残了，黛玉倒要留着听雨。","place":"huaxu","hui":[40],"img":{"full":"dgy-assets/huace/img/zhouru-05.webp","thumb":"dgy-assets/huace/img/zhouru-05-s.webp"},"画面":"秋日白天，一只棠木舫驶近萝港：石洞口萝薜倒垂，阴森；岸边衰草残菱，水面破荷叶。船里黛玉抬头望着残荷，宝玉回话，宝钗在旁；迎春探春惜春坐在船尾，侧身。","quote":{"文":"林黛玉道：「我最不喜歡李義山的詩，只喜他這一句：『留得殘荷聽雨聲』。偏你們又不留著殘荷了。」寶玉道：「果然好句，以後咱們就別叫人拔去了。」說著已到了花漵的蘿港之下，覺得陰森透骨，兩灘上衰草殘菱，更助秋情。","回":40}},"chufang:1":{"n":"柳家的厨房·第1幅","t":"园中厨房","册":"chufang","幅":1,"line":"「一面來至廚房，——雖有幾個同伴的人，他們都不敢自專，單等他來調停分派——一面問眾人：「五丫頭那去了？」」迎春房的莲花儿接着来要一碗嫩嫩的炖鸡蛋。柳家的说鸡蛋短，莲花儿翻出菜箱里的鸡蛋，吵了起来。她一进门先问五丫头，心里挂着女儿进怡红院的事。后头的玫瑰露、茯苓霜，都是从这一问里牵出来的。","place":"kitchen","hui":[61],"img":{"full":"dgy-assets/huace/img/chufang-01.webp","thumb":"dgy-assets/huace/img/chufang-01-s.webp"},"画面":"柳家的推门进了厨房：灶台、菜箱、案板；几个同伴站着不敢自作主张，等她分派；她一边问五丫头去哪了，一边按房头分菜。","quote":{"文":"一面來至廚房，——雖有幾個同伴的人，他們都不敢自專，單等他來調停分派——一面問眾人：「五丫頭那去了？」","回":61}},"chufang:2":{"n":"柳家的厨房·第2幅","t":"园中厨房","册":"chufang","幅":2,"line":"「司棋便喝命小丫頭子動手，「凡箱櫃所有的菜蔬，只管丟出去餵狗，大家賺不成。」小丫頭子們巴不得一聲，七手八腳搶上去，一頓亂翻亂擲的。」莲花儿回去添油加醋，司棋才起火。主子是人称二木头的迎春（第65回），大丫头倒最泼辣。主子不出头，司棋便替她出头。","place":"kitchen","hui":[61],"img":{"full":"dgy-assets/huace/img/chufang-02.webp","thumb":"dgy-assets/huace/img/chufang-02-s.webp"},"画面":"厨房里人正在吃饭，司棋带着小丫头闯进来，喝命把菜丢出去喂狗；小丫头们七手八脚翻箱倒柜，菜蔬撒了一地；几个人拉的拉、劝的劝。","quote":{"文":"司棋便喝命小丫頭子動手，「凡箱櫃所有的菜蔬，只管丟出去餵狗，大家賺不成。」小丫頭子們巴不得一聲，七手八腳搶上去，一頓亂翻亂擲的。","回":61}},"chufang:3":{"n":"柳家的厨房·第3幅","t":"园中厨房","册":"chufang","幅":3,"line":"「柳家的只好摔碗丟盤自己咕嘟了一回，蒸了一碗蛋令人送去。司棋全潑了地下了。」司棋闹过一场，被劝走了。这碗蛋是补上的，仍然被泼。柳家的嘴里嘟囔，手上还是蒸了，算是认了错；司棋连认错也不收。一碗鸡蛋，泼的是二姑娘屋里的体面。","place":"kitchen","hui":[61],"img":{"full":"dgy-assets/huace/img/chufang-03.webp","thumb":"dgy-assets/huace/img/chufang-03-s.webp"},"画面":"人散了。柳家的自己摔碗丢盘，嘟囔着，还是蒸了一碗蛋让人送去；送去的人回来，站在门口低头不敢说话，地上有一团泼了的蛋。","quote":{"文":"柳家的只好摔碗丟盤自己咕嘟了一回，蒸了一碗蛋令人送去。司棋全潑了地下了。","回":61}},"chufang:4":{"n":"柳家的厨房·第4幅","t":"园中厨房","册":"chufang","幅":4,"line":"「那秦顯家的好容易等了這個空子鑽了來，只興頭上半天。在廚房內正亂著接收傢伙米糧煤炭等物，又查出許多虧空來，說：「粳米短了兩石，常用米又多支了一個月的，炭也欠著額數。」」柳家的母女被带走之后，秦显家的趁空子顶了差事，只得意了半天。她来得快，账上的窟窿露得也快。一个厨房，人人都盯着这点油水。","place":"kitchen","hui":[62],"img":{"full":"dgy-assets/huace/img/chufang-04.webp","thumb":"dgy-assets/huace/img/chufang-04-s.webp"},"画面":"厨房里，秦显家的在接收锅盆、米、炭，手忙脚乱，账本摊在案上；旁边的人念着短了两石粳米、多支了一个月的常用米、炭也欠着额数。","quote":{"文":"那秦顯家的好容易等了這個空子鑽了來，只興頭上半天。在廚房內正亂著接收傢伙米糧煤炭等物，又查出許多虧空來，說：「粳米短了兩石，常用米又多支了一個月的，炭也欠著額數。」","回":62}},"chufang:5":{"n":"柳家的厨房·第5幅","t":"园中厨房","册":"chufang","幅":5,"line":"「正亂著，忽有人來說與他：「看過這早飯就出去罷。柳嫂兒原無事，如今還交與他管了。」秦顯家的聽了，轟去魂魄，垂頭喪氣，登時掩旗息鼓，卷包而出。」平儿说“大事化为小事，小事化为没事”，让柳家的母女照旧当差。秦显家的送出去的礼白丢了，还要折变了赔补亏空。送出去的礼白丢了，还要赔亏空。厨房这个差事，进得去的未必坐得住，全看平儿一句话。","place":"kitchen","hui":[62],"img":{"full":"dgy-assets/huace/img/chufang-05.webp","thumb":"dgy-assets/huace/img/chufang-05-s.webp"},"画面":"秦显家的正请同事们吃饭、摆着菜蔬；有人进门说话，她听了脸色发白，垂头丧气，收拾包袱往外走。","quote":{"文":"正亂著，忽有人來說與他：「看過這早飯就出去罷。柳嫂兒原無事，如今還交與他管了。」秦顯家的聽了，轟去魂魄，垂頭喪氣，登時掩旗息鼓，卷包而出。","回":62}},"gongdu:1":{"n":"共读西厢·第1幅","t":"沁芳闸","册":"gongdu","幅":1,"line":"「那一日正當三月中浣，早飯後，寶玉攜了一套《會真記》，走到沁芳閘橋邊桃花底下一塊石上坐著，展開《會真記》，從頭細玩。正看到「落紅成陣」」书是他带进园的。桥就是第十七回那座引水的闸桥。书是茗烟从书坊买来的，宝玉只挑「文理細密」的几套带进园，粗俗的都藏在外面书房里。","place":"qinfangzha","hui":[23],"img":{"full":"dgy-assets/huace/img/gongdu-01.webp","thumb":"dgy-assets/huace/img/gongdu-01-s.webp"},"画面":"三月，沁芳闸桥边，桃花盛开，树下一块大石。宝玉坐在石上，展开一本书，低头细看（书页留空，不画字）。","quote":{"文":"那一日正當三月中浣，早飯後，寶玉攜了一套《會真記》，走到沁芳閘橋邊桃花底下一塊石上坐著，展開《會真記》，從頭細玩。正看到「落紅成陣」","回":23}},"gongdu:2":{"n":"共读西厢·第2幅","t":"沁芳闸","册":"gongdu","幅":2,"line":"「只見一陣風過，把樹頭上桃花吹下一大半來，落的滿身滿書滿地皆是。」他要抖花，又怕踩坏了落花。书上正读到落红成阵，树上就真落了一阵。曹公借一阵风，给西厢记添了一笔。宝玉舍不得让花落在脚下，先收进衣襟，书页上的情词也就暂被眼前的落英打断；等黛玉走来，两样事才接到一处。","place":"qinfangzha","hui":[23],"img":{"full":"dgy-assets/huace/img/gongdu-02.webp","thumb":"dgy-assets/huace/img/gongdu-02-s.webp"},"画面":"一阵风过，桃花落下大半，落了宝玉满身、满书、满地。他捧着书站起，想抖，又怕脚下踩坏花瓣。","quote":{"文":"只見一陣風過，把樹頭上桃花吹下一大半來，落的滿身滿書滿地皆是。","回":23}},"gongdu:3":{"n":"共读西厢·第3幅","t":"沁芳闸","册":"gongdu","幅":3,"line":"「寶玉要抖將下來，恐怕腳步踐踏了，只得兜了那花瓣，來至池邊，抖在池內。那花瓣浮在水面，飄飄蕩蕩，竟流出沁芳閘去了。」第二十七回他再来，兜的是凤仙、石榴，奔的就是第二十三回黛玉说的那个花冢。花随水出了沁芳闸，出园便是外头的人间。园里的东西，一出闸就由不得自己。","place":"qinfangzha","hui":[23],"img":{"full":"dgy-assets/huace/img/gongdu-03.webp","thumb":"dgy-assets/huace/img/gongdu-03-s.webp"},"画面":"宝玉兜着一兜花瓣，走到池边抖进水里；花瓣浮在水面，飘飘荡荡，向沁芳闸口流去。","quote":{"文":"寶玉要抖將下來，恐怕腳步踐踏了，只得兜了那花瓣，來至池邊，抖在池內。那花瓣浮在水面，飄飄蕩蕩，竟流出沁芳閘去了。","回":23}},"gongdu:4":{"n":"共读西厢·第4幅","t":"沁芳闸","册":"gongdu","幅":4,"line":"「寶玉一回頭，卻是林黛玉來了，肩上擔著花鋤，鋤上掛著花囊，手內拿著花帚。寶玉笑道：「好，好，來把這個花掃起來，撂在那水裡。我才撂了好些在那裡呢。」林黛玉道：「撂在水裡不好。你看這裡的水乾淨，只一流出去，有人家的地方髒的臭的混倒，仍舊把花遭塌了。那畸角上我有一個花冢，如今把他掃了，裝在這絹袋裡，拿土埋上，日久不過隨土化了，豈不乾淨。」」葬花从这里开始：花冢在“畸角上”。第二十七回芒种那天的哭诵，说的就是这个花冢。宝玉只想到别踩着，黛玉想到了流出去以后。她看花，向来比人多看一步。","place":"qinfangzha","hui":[23],"img":{"full":"dgy-assets/huace/img/gongdu-04.webp","thumb":"dgy-assets/huace/img/gongdu-04-s.webp"},"画面":"黛玉从背后来，肩上担着花锄，锄上挂着花囊，手里拿着花帚；宝玉笑着回头；黛玉摇头，指着池水，说那水流出去会脏，要装进绢袋拿土埋了。","quote":{"文":"寶玉一回頭，卻是林黛玉來了，肩上擔著花鋤，鋤上掛著花囊，手內拿著花帚。寶玉笑道：「好，好，來把這個花掃起來，撂在那水裡。我才撂了好些在那裡呢。」林黛玉道：「撂在水裡不好。你看這裡的水乾淨，只一流出去，有人家的地方髒的臭的混倒，仍舊把花遭塌了。那畸角上我有一個花冢，如今把他掃了，裝在這絹袋裡，拿土埋上，日久不過隨土化了，豈不乾淨。」","回":23}},"gongdu:5":{"n":"共读西厢·第5幅","t":"沁芳闸","册":"gongdu","幅":5,"line":"「寶玉笑道：「我就是個『多愁多病身』，你就是那『傾國傾城貌』。」林黛玉聽了，不覺帶腮連耳通紅，登時直豎起兩道似蹙非蹙的眉，瞪了兩隻似睜非睜的眼，微腮帶怒，薄面含嗔，指寶玉道：「你這該死的胡說！好好的把這淫詞艷曲弄了來，還學了這些混話來欺負我。我告訴舅舅舅母去。」」《会真记》就是《西厢记》。黛玉随后被宝玉的赌咒逗得又笑了，还用戏词回他“银样镴枪头”。人没有离开这块石头。宝玉借戏词说真心，黛玉恼是恼，转眼又借戏词回他。两个人的真话，都得托戏文说出来。","place":"qinfangzha","hui":[23],"img":{"full":"dgy-assets/huace/img/gongdu-05.webp","thumb":"dgy-assets/huace/img/gongdu-05-s.webp"},"画面":"两人还在桃花下。宝玉笑着说了那两句；黛玉红到耳朵，竖起眉毛，瞪着眼，伸手指着他，眼圈红了。","quote":{"文":"寶玉笑道：「我就是個『多愁多病身』，你就是那『傾國傾城貌』。」林黛玉聽了，不覺帶腮連耳通紅，登時直豎起兩道似蹙非蹙的眉，瞪了兩隻似睜非睜的眼，微腮帶怒，薄面含嗔，指寶玉道：「你這該死的胡說！好好的把這淫詞艷曲弄了來，還學了這些混話來欺負我。我告訴舅舅舅母去。」","回":23}},"qujing:1":{"n":"曲径通幽·第1幅","t":"翠嶂","册":"qujing","幅":1,"line":"「眾清客都道：「好山，好山！」賈政道：「非此一山，一進來園中所有之景悉入目中，則有何趣。」」山是遮景的：有了它，进门不会一眼把园子看尽。清客只会叫两声好，遮景的道理倒是贾政说出来的。可知他并非不懂园子，只是不懂儿子。","place":"cuizhang","hui":[17],"img":{"full":"dgy-assets/huace/img/qujing-01.webp","thumb":"dgy-assets/huace/img/qujing-01-s.webp"},"画面":"门内，翠嶂挡在正前方。清客们仰头赞好山；贾政抬手指着山说话；宝玉站在贾政身后侧，垂手听着。","quote":{"文":"眾清客都道：「好山，好山！」賈政道：「非此一山，一進來園中所有之景悉入目中，則有何趣。」","回":17}},"qujing:2":{"n":"曲径通幽·第2幅","t":"翠嶂","册":"qujing","幅":2,"line":"「說畢，往前一望，見白石峻嶒，或如鬼怪，或如猛獸，縱橫拱立，上面苔蘚成斑，藤蘿掩映，其中微露羊腸小徑。」人从这条小径走进去，不从正中翻山。进园头一眼，不是花柳，是一片似鬼似兽的白石。富贵园子的门，原是从冷硬处开的。","place":"cuizhang","hui":[17],"img":{"full":"dgy-assets/huace/img/qujing-02.webp","thumb":"dgy-assets/huace/img/qujing-02-s.webp"},"画面":"山石白而陡峭，有的像鬼怪、有的像猛兽，纵横拱立；上面苔藓成斑，藤萝掩映；石缝里露出一条羊肠小径。无人，或只有极小的背影。","quote":{"文":"說畢，往前一望，見白石峻嶒，或如鬼怪，或如猛獸，縱橫拱立，上面苔蘚成斑，藤蘿掩映，其中微露羊腸小徑。","回":17}},"qujing:3":{"n":"曲径通幽·第3幅","t":"翠嶂","册":"qujing","幅":3,"line":"「說畢，命賈珍在前引導，自己扶了寶玉，逶迤進入山口。抬頭忽見山上有鏡面白石一塊，正是迎面留題處。」这块镜面白石就是留着题字的地方。清客们先凑了「疊翠」「錦嶂」「賽香爐」「小終南」，都是敷衍的俗套。一路要喝骂的父亲，进山口这一步，倒是伸手扶着儿子走的。贾政的疼，只肯落在手上，不肯落在嘴上。","place":"cuizhang","hui":[17],"img":{"full":"dgy-assets/huace/img/qujing-03.webp","thumb":"dgy-assets/huace/img/qujing-03-s.webp"},"画面":"山口。贾珍在前面引路，贾政一手扶着宝玉的肩，弯进山口；抬头，山壁上一块磨得平整的白石，石面空白光滑（不画任何字）。","quote":{"文":"說畢，命賈珍在前引導，自己扶了寶玉，逶迤進入山口。抬頭忽見山上有鏡面白石一塊，正是迎面留題處。","回":17}},"qujing:4":{"n":"曲径通幽·第4幅","t":"翠嶂","册":"qujing","幅":4,"line":"「寶玉道：「嘗聞古人有云：『編新不如述舊，刻古終勝雕今。』況此處並非主山正景，原無可題之處，不過是探景一進步耳。莫若直書『曲徑通幽處』這句舊詩在上，倒還大方氣派。」」他用的是旧诗，不另造新名：「编新不如述旧」。众人都夸，贾政笑说「不可谬奖」。他自知此处不是正景，只借一句旧诗，不抢后头的风头。贾政说「不可謬獎」，是压着的得意。","place":"cuizhang","hui":[17],"img":{"full":"dgy-assets/huace/img/qujing-04.webp","thumb":"dgy-assets/huace/img/qujing-04-s.webp"},"画面":"宝玉站在镜面白石前，抬手指着石面说话；贾政半侧身微笑，清客们点头附和。石面仍是空白（不画字）。","quote":{"文":"寶玉道：「嘗聞古人有云：『編新不如述舊，刻古終勝雕今。』況此處並非主山正景，原無可題之處，不過是探景一進步耳。莫若直書『曲徑通幽處』這句舊詩在上，倒還大方氣派。」","回":17}},"qujing:5":{"n":"曲径通幽·第5幅","t":"翠嶂","册":"qujing","幅":5,"line":"「說著，進入石洞來。只見佳木蘢蔥，奇花閃灼，一帶清流，從花木深處曲折瀉於石隙之下。」出了洞，才是北边的池和沁芳亭。这一幅停在洞里的水。这一线清流，出洞便是沁芳溪。后来桃花落在水上，宝玉兜了去抖，黛玉嫌它流出去脏（第23回）。","place":"cuizhang","hui":[17],"img":{"full":"dgy-assets/huace/img/qujing-05.webp","thumb":"dgy-assets/huace/img/qujing-05-s.webp"},"画面":"石洞里面：草木深而茂，奇花闪着光，一股清水从花木深处弯弯曲曲泻到石缝底下。洞中小路上，贾政和清客的背影，往里走。","quote":{"文":"說著，進入石洞來。只見佳木蘢蔥，奇花閃灼，一帶清流，從花木深處曲折瀉於石隙之下。","回":17}},"zilingge:1":{"n":"紫菱洲歌·第1幅","t":"紫菱洲","册":"zilingge","幅":1,"line":"「因此天天到紫菱洲一帶地方徘徊瞻顧，見其軒窗寂寞，屏帳翛然，不過有幾個該班上夜的老嫗。」迎春许了孙家，人已经搬出大观园。宝玉是天天来。人搬走了，上夜的老妪照旧该班，守的是一座空楼。迎春在时本不大有声响，人去了，这院子才显出空来。","place":"ziling","hui":[79],"img":{"full":"dgy-assets/huace/img/zilingge-01.webp","thumb":"dgy-assets/huace/img/zilingge-01-s.webp"},"画面":"秋日白天，临水的缀锦楼：轩窗紧闭，窗内屏帐空落；廊下只有两三个老妪缩着坐。宝玉一个人在水边廊外慢慢地走，抬头望着楼窗，神情失落。","quote":{"文":"因此天天到紫菱洲一帶地方徘徊瞻顧，見其軒窗寂寞，屏帳翛然，不過有幾個該班上夜的老嫗。","回":79}},"zilingge:2":{"n":"紫菱洲歌·第2幅","t":"紫菱洲","册":"zilingge","幅":2,"line":"「再看那岸上的蓼花葦葉，池內的翠荇香菱，也都覺搖搖落落，似有追憶故人之態，迥非素常逞妍鬥色之可比。」地名紫菱洲，这一眼就是菱、蓼、苇、荇，都是要落的样子。池里有「香菱」，下一幅便来了一个香菱。曹公埋名字，向来不动声色。","place":"ziling","hui":[79],"img":{"full":"dgy-assets/huace/img/zilingge-02.webp","thumb":"dgy-assets/huace/img/zilingge-02-s.webp"},"画面":"岸上蓼花、苇叶摇摇落落；池里荇菜、菱叶稀稀疏疏，半枯的叶子浮在水上。宝玉站在水边看，背影侧身，衣角被风吹动。","quote":{"文":"再看那岸上的蓼花葦葉，池內的翠荇香菱，也都覺搖搖落落，似有追憶故人之態，迥非素常逞妍鬥色之可比。","回":79}},"zilingge:3":{"n":"紫菱洲歌·第3幅","t":"紫菱洲","册":"zilingge","幅":3,"line":"「池塘一夜秋風冷，吹散芰荷紅玉影。蓼花菱葉不勝愁，重露繁霜壓纖梗。不聞永晝敲棋聲，燕泥點點污棋枰。古人惜別憐朋友，況我今當手足情！」底本这首歌是这四句，到「手足情」为止。琴棋书画四个丫头，跟迎春的叫司棋。棋声断了，司棋也早被撵出去了（第77回）。","place":"ziling","hui":[79],"img":{"full":"dgy-assets/huace/img/zilingge-03.webp","thumb":"dgy-assets/huace/img/zilingge-03-s.webp"},"画面":"宝玉对着空池吟诗，没有纸笔，嘴唇微动，目光落在池面。岸上蓼花菱叶在冷风里，水面残荷红影被吹散。","quote":{"文":"池塘一夜秋風冷，吹散芰荷紅玉影。蓼花菱葉不勝愁，重露繁霜壓纖梗。不聞永晝敲棋聲，燕泥點點污棋枰。古人惜別憐朋友，況我今當手足情！","回":79}},"zilingge:4":{"n":"紫菱洲歌·第4幅","t":"紫菱洲","册":"zilingge","幅":4,"line":"「寶玉方才吟罷，忽聞背後有人笑道：「你又發什麼呆呢？」寶玉回頭忙看是誰，原來是香菱。」香菱是进园找凤姐，路过这里遇见他，随后要去稻香村。她接着说的是：「二姑娘搬出去的好快，你瞧瞧这地方好空落落的。」香菱笑他发呆，转眼便盼新奶奶进门添个诗伴。宝玉替她「耽心慮後」，她倒红了脸。园里最痴的不是宝玉。","place":"ziling","hui":[79],"img":{"full":"dgy-assets/huace/img/zilingge-04.webp","thumb":"dgy-assets/huace/img/zilingge-04-s.webp"},"画面":"宝玉刚吟罢，回头：香菱从背后走来，拍着手笑，伸手指着空荡荡的楼窗，说二姑娘搬得好快。宝玉和香菱面对面，背景是紫菱洲的楼。","quote":{"文":"寶玉方才吟罷，忽聞背後有人笑道：「你又發什麼呆呢？」寶玉回頭忙看是誰，原來是香菱。","回":79}},"kanhua:1":{"n":"暖香坞看画·第1幅","t":"暖香坞","册":"kanhua","幅":1,"line":"「向外的匾上鑿著「穿雲」二字，向裡的鑿著「度月」兩字。來至當中，進了向南的正門，賈母下了轎，惜春已接了出來。從裡邊遊廊過去，便是惜春臥房，門斗上有「暖香塢」三個字。早有幾個人打起猩紅氈簾，已覺溫香拂臉。」院名蓼风轩，房匾暖香坞，正门朝南。穿云、度月是夹道门上的石匾。过街门上，向外是穿云，向里是度月。惜春的院子，连夹道的门都题得像要出世。","place":"nuanxiang","hui":[50],"img":{"full":"dgy-assets/huace/img/kanhua-01.webp","thumb":"dgy-assets/huace/img/kanhua-01-s.webp"},"画面":"大雪天，夹道西边的过街门，石匾空白（不画字）。贾母坐小竹轿，围大斗篷、戴灰鼠暖兜，鸳鸯琥珀等丫鬟打伞拥轿；惜春迎出门来。卧房门斗上一块空白匾，猩红毡帘已被掀起。","quote":{"文":"向外的匾上鑿著「穿雲」二字，向裡的鑿著「度月」兩字。來至當中，進了向南的正門，賈母下了轎，惜春已接了出來。從裡邊遊廊過去，便是惜春臥房，門斗上有「暖香塢」三個字。早有幾個人打起猩紅氈簾，已覺溫香拂臉。","回":50}},"kanhua:2":{"n":"暖香坞看画·第2幅","t":"暖香坞","册":"kanhua","幅":2,"line":"「大家進入房中，賈母並不歸坐，只問畫在那裡。惜春因笑問：「天氣寒冷了，膠性皆凝澀不潤，畫了恐不好看，故此收起來。」」大观园图还没画完。这就是回目里「看画」的由来。众人早替她议定了半年的假，画一直慢（第42回）。天冷胶涩，是她最体面的一句托词。","place":"nuanxiang","hui":[50],"img":{"full":"dgy-assets/huace/img/kanhua-02.webp","thumb":"dgy-assets/huace/img/kanhua-02-s.webp"},"画面":"屋里暖和，一幅暖色。贾母站着不坐，四处看；惜春笑着摆手解释，桌上只有颜料碟和空画案，画已经收起来了。","quote":{"文":"大家進入房中，賈母並不歸坐，只問畫在那裡。惜春因笑問：「天氣寒冷了，膠性皆凝澀不潤，畫了恐不好看，故此收起來。」","回":50}},"kanhua:3":{"n":"暖香坞看画·第3幅","t":"暖香坞","册":"kanhua","幅":3,"line":"「賈母笑道：「我年下就要的。你別拖懶兒，快拿出來給我快畫。」」先前在芦雪广，贾母说「趕年可有了」，众人笑说「只怕明年端阳」，贾母说「这还了得」。催画的是贾母本人。催的是画，惦的是园。一园子人聚得这样齐，老太太心里有数，等不得。","place":"nuanxiang","hui":[50],"img":{"full":"dgy-assets/huace/img/kanhua-03.webp","thumb":"dgy-assets/huace/img/kanhua-03-s.webp"},"画面":"贾母站着，手指惜春，催她快拿出来；惜春低头为难，手攥着衣带。","quote":{"文":"賈母笑道：「我年下就要的。你別拖懶兒，快拿出來給我快畫。」","回":50}},"kanhua:4":{"n":"暖香坞看画·第4幅","t":"暖香坞","册":"kanhua","幅":4,"line":"「一語未了，忽見鳳姐兒披著紫羯褂，笑嘻嘻的來了，口內說道：「老祖宗今兒也不告訴人，私自就來了，要我好找。」」凤姐接着说，园里来了姑子送年疏，老祖宗是躲债来了，已替她把年例给了。凤姐一句躲债的笑话，把老太太从冷屋里哄了出去，又顺手把年例的功劳记在自己账上。","place":"nuanxiang","hui":[50],"img":{"full":"dgy-assets/huace/img/kanhua-04.webp","thumb":"dgy-assets/huace/img/kanhua-04-s.webp"},"画面":"凤姐披着紫羯褂，笑嘻嘻掀帘进来；贾母回头，脸上是喜悦；惜春在旁。","quote":{"文":"一語未了，忽見鳳姐兒披著紫羯褂，笑嘻嘻的來了，口內說道：「老祖宗今兒也不告訴人，私自就來了，要我好找。」","回":50}},"kanhua:5":{"n":"暖香坞看画·第5幅","t":"暖香坞","册":"kanhua","幅":5,"line":"「次日雪晴。飯後，賈母又親囑惜春：「不管冷暖，你只畫去，趕到年下，十分不能便罷了。第一要緊把昨日琴兒和丫頭梅花，照模照樣，一筆別錯，快快添上。」」宝琴和丫头立在红梅边的样子，是前一天出夹道东门时看到的。惜春听了为难，只是出神。要添的不是园景，是宝琴。同一回里，贾母还细问了琴儿的「年庚八字」。一幅园图，画的是老太太的心思。","place":"nuanxiang","hui":[50],"img":{"full":"dgy-assets/huace/img/kanhua-05.webp","thumb":"dgy-assets/huace/img/kanhua-05-s.webp"},"画面":"次日雪晴，窗外积雪发亮。惜春坐在案前，面前铺着一幅未画完的画，手握画笔出神；贾母站在她身边叮嘱；门口几个姐妹探头看。","quote":{"文":"次日雪晴。飯後，賈母又親囑惜春：「不管冷暖，你只畫去，趕到年下，十分不能便罷了。第一要緊把昨日琴兒和丫頭梅花，照模照樣，一筆別錯，快快添上。」","回":50}},"tianran:1":{"n":"稻香村争天然·第1幅","t":"稻香村","册":"tianran","幅":1,"line":"「轉過山懷中，隱隱露出一帶黃泥築就矮牆，牆頭皆用稻莖掩護。有幾百株杏花，如噴火蒸霞一般。裡面數楹茅屋。外面卻是桑，榆，槿，柘，各色樹稚新條，隨其曲折，編就兩溜青籬。籬外山坡之下，有一土井，旁有桔槔轆轤之屬。下面分畦列畝，佳蔬菜花，漫然無際。」贾政觉得这里有道理，想进去歇一歇。酒幌这时还没有，是他当场吩咐做的。井有桔槔，畦有菜花，件件是真庄户的家伙。贾政看了「勾引起我歸農之意」，这心思也是造出来的。","place":"daoxiang","hui":[17],"img":{"full":"dgy-assets/huace/img/tianran-01.webp","thumb":"dgy-assets/huace/img/tianran-01-s.webp"},"画面":"黄泥矮墙，墙头盖着稻茎；几百株杏花红成一片；里面几间茅屋；外面桑、榆、槿、柘编成两溜青篱；篱外山坡下一口土井，旁边桔槔辘轳；下面成畦的菜花。远处贾政和清客立在篱外，背影。","quote":{"文":"轉過山懷中，隱隱露出一帶黃泥築就矮牆，牆頭皆用稻莖掩護。有幾百株杏花，如噴火蒸霞一般。裡面數楹茅屋。外面卻是桑，榆，槿，柘，各色樹稚新條，隨其曲折，編就兩溜青籬。籬外山坡之下，有一土井，旁有桔槔轆轤之屬。下面分畦列畝，佳蔬菜花，漫然無際。","回":17}},"tianran:2":{"n":"稻香村争天然·第2幅","t":"稻香村","册":"tianran","幅":2,"line":"「此處都妙極，只是還少一個酒幌。明日竟作一個，不必華麗，就依外面村莊的式樣作來，用竹竿挑在樹梢。」賈珍答應了，又回道：「此處竟還不可養別的雀鳥，只是買些鵝鴨雞類，才都相稱了。」清客想题「杏花村」，贾政说犯了正名，村名要等贵妃来题。连该养鹅鸭还是雀鸟都算到了。做一个假村庄，贾府的人比真庄户还讲究相称。","place":"daoxiang","hui":[17],"img":{"full":"dgy-assets/huace/img/tianran-02.webp","thumb":"dgy-assets/huace/img/tianran-02-s.webp"},"画面":"篱门外路旁一块石碣，石面空白（不画字）。贾政指着村口比划，吩咐做一面酒幌，用竹竿挑在树梢；贾珍躬身答应，又回话说这里只宜养鹅鸭鸡。","quote":{"文":"此處都妙極，只是還少一個酒幌。明日竟作一個，不必華麗，就依外面村莊的式樣作來，用竹竿挑在樹梢。」賈珍答應了，又回道：「此處竟還不可養別的雀鳥，只是買些鵝鴨雞類，才都相稱了。","回":17}},"tianran:3":{"n":"稻香村争天然·第3幅","t":"稻香村","册":"tianran","幅":3,"line":"「寶玉卻等不得了，也不等賈政的命，便說道：「舊詩有云：『紅杏梢頭掛酒旗』。如今莫若『杏簾在望』四字。」眾人都道：「好個『在望』！又暗合『杏花村』意。」寶玉冷笑道：「村名若用『杏花』二字，則俗陋不堪了。又有古人詩云：『柴門臨水稻花香』，何不就用『稻香村』的妙？」」元春后来先赐「浣葛山庄」，评了宝玉那首《杏帘在望》才改称稻香村。试才这一天，宝玉已经说出「稻香村」。清客拍手叫妙，贾政一声断喝。赞是清客的饭碗，骂是父亲的规矩，两边都不是冲着那三个字去的。","place":"daoxiang","hui":[17],"img":{"full":"dgy-assets/huace/img/tianran-03.webp","thumb":"dgy-assets/huace/img/tianran-03-s.webp"},"画面":"宝玉不等吩咐就开口，抬手指着石碣；清客们拍手叫好，贾政气得断喝。石碣空白（不画字）。","quote":{"文":"寶玉卻等不得了，也不等賈政的命，便說道：「舊詩有云：『紅杏梢頭掛酒旗』。如今莫若『杏簾在望』四字。」眾人都道：「好個『在望』！又暗合『杏花村』意。」寶玉冷笑道：「村名若用『杏花』二字，則俗陋不堪了。又有古人詩云：『柴門臨水稻花香』，何不就用『稻香村』的妙？」","回":17}},"tianran:4":{"n":"稻香村争天然·第4幅","t":"稻香村","册":"tianran","幅":4,"line":"「眾人忙道：「別的都明白，為何連『天然』不知？『天然』者，天之自然而有，非人力之所成也。」寶玉道：「卻又來！此處置一田莊，分明見得人力穿鑿扭捏而成。遠無鄰村，近不負郭，背山山無脈，臨水水無源，高無隱寺之塔，下無通市之橋，峭然孤出，似非大觀。」贾政爱这里清幽，宝玉偏说不及「有凤来仪」，争的是「天然」：这个田庄是人力穿凿出来的。宝玉驳的是一个稻香村，说中的是整座园子：哪一处不是平地堆出来的山水。贾政动气，是被说中了。","place":"daoxiang","hui":[17],"img":{"full":"dgy-assets/huace/img/tianran-04.webp","thumb":"dgy-assets/huace/img/tianran-04-s.webp"},"画面":"茅堂里：纸窗木榻，清清素素。宝玉面对贾政，伸手比划着说话；贾政瞅着他，脸色发沉；清客在旁边干着急。","quote":{"文":"眾人忙道：「別的都明白，為何連『天然』不知？『天然』者，天之自然而有，非人力之所成也。」寶玉道：「卻又來！此處置一田莊，分明見得人力穿鑿扭捏而成。遠無鄰村，近不負郭，背山山無脈，臨水水無源，高無隱寺之塔，下無通市之橋，峭然孤出，似非大觀。","回":17}},"tianran:5":{"n":"稻香村争天然·第5幅","t":"稻香村","册":"tianran","幅":5,"line":"「新漲綠添浣葛處，好雲香護採芹人。」这一联后来没被摘掉：元春下令旧有匾联都不必摘去（第18回）。叉出去，又喝回来，骂归骂，还要听儿子下一句。联里的浣葛二字，元春后来拿去作了村名（第18回）。","place":"daoxiang","hui":[17],"img":{"full":"dgy-assets/huace/img/tianran-05.webp","thumb":"dgy-assets/huace/img/tianran-05-s.webp"},"画面":"茅堂里，贾政气得拍案，喝命把宝玉叉出去，又喝他回来再题一联，不通就打嘴；宝玉低头垂手，念出两句，贾政听完摇头。","quote":{"文":"新漲綠添浣葛處，好雲香護採芹人。","回":17}},"chixie:1":{"n":"藕香榭持螯赏桂·第1幅","t":"藕香榭","册":"chixie","幅":1,"line":"「鳳姐道：「藕香榭已經擺下了，那山坡下兩棵桂花開的又好，河裡的水又碧清，坐在河當中亭子上豈不敞亮，看著水眼也清亮。」」席是湘云做东，宝钗帮着预备。凤姐先把地方定在了这里。席是湘云做东，地方却是凤姐挑的。水碧清、眼也清亮，句句是说给老太太一个人听的。","place":"ouxiang","hui":[38],"img":{"full":"dgy-assets/huace/img/chixie-01.webp","thumb":"dgy-assets/huace/img/chixie-01-s.webp"},"画面":"白天，水边山坡下两棵桂花开得正好。凤姐扶着贾母往水边走，抬手指着池中的亭子；湘云笑着跟在后面；王夫人等在远景。","quote":{"文":"鳳姐道：「藕香榭已經擺下了，那山坡下兩棵桂花開的又好，河裡的水又碧清，坐在河當中亭子上豈不敞亮，看著水眼也清亮。」","回":38}},"chixie:2":{"n":"藕香榭持螯赏桂·第2幅","t":"藕香榭","册":"chixie","幅":2,"line":"「原來這藕香榭蓋在池中，四面有窗，左右有曲廊可通，亦是跨水接岸，後面又有曲折竹橋暗接。眾人上了竹橋，鳳姐忙上來攙著賈母，口裡說：「老祖宗只管邁大步走，不相干的，這竹子橋規矩是咯吱咯喳的。」」栏杆外另设着两张竹案：一边是酒具，一边是茶具，丫头在煽风炉煮茶、烫酒。上了亭子，贾母便说起小时候家里的「枕霞閣」，失脚落水碰破了头。湘云的别号枕霞旧友，就从这里来。","place":"ouxiang","hui":[38],"img":{"full":"dgy-assets/huace/img/chixie-02.webp","thumb":"dgy-assets/huace/img/chixie-02-s.webp"},"画面":"池中一座水榭，四面有窗，左右曲廊，跨水接岸，后面一道曲折的竹桥。贾母走在曲折的竹桥上，脚步小心，凤姐在旁搀着她、笑着说话。","quote":{"文":"原來這藕香榭蓋在池中，四面有窗，左右有曲廊可通，亦是跨水接岸，後面又有曲折竹橋暗接。眾人上了竹橋，鳳姐忙上來攙著賈母，口裡說：「老祖宗只管邁大步走，不相干的，這竹子橋規矩是咯吱咯喳的。」","回":38}},"chixie:3":{"n":"藕香榭持螯赏桂·第3幅","t":"藕香榭","册":"chixie","幅":3,"line":"「鳳姐吩咐：「螃蟹不可多拿來，仍舊放在蒸籠裡，拿十個來，吃了再拿。」一面又要水洗了手，站在賈母跟前剝蟹肉，頭次讓薛姨媽。薛姨媽道：「我自己掰著吃香甜，不用人讓。」鳳姐便奉與賈母。二次的便與寶玉，又說：「把酒燙的滾熱的拿來。」又命小丫頭們去取菊花葉兒桂花蕊熏的綠豆面子來，預備洗手。」薛姨妈自己掰着吃香甜，不用人让。凤姐自己不坐，站着剥。先让客，再敬老，末了才轮到宝玉，次序一丝不乱，这是她的本事。","place":"ouxiang","hui":[38],"img":{"full":"dgy-assets/huace/img/chixie-03.webp","thumb":"dgy-assets/huace/img/chixie-03-s.webp"},"画面":"榭里摆席。凤姐吩咐螃蟹仍放在蒸笼里先拿十个，她洗了手，站在贾母跟前剥蟹肉，先奉给贾母，第二份递给宝玉；小丫头去取菊花叶、桂花蕊熏的绿豆面子，预备洗手。","quote":{"文":"鳳姐吩咐：「螃蟹不可多拿來，仍舊放在蒸籠裡，拿十個來，吃了再拿。」一面又要水洗了手，站在賈母跟前剝蟹肉，頭次讓薛姨媽。薛姨媽道：「我自己掰著吃香甜，不用人讓。」鳳姐便奉與賈母。二次的便與寶玉，又說：「把酒燙的滾熱的拿來。」又命小丫頭們去取菊花葉兒桂花蕊熏的綠豆面子來，預備洗手。","回":38}},"chixie:4":{"n":"藕香榭持螯赏桂·第4幅","t":"藕香榭","册":"chixie","幅":4,"line":"「今日公評：《詠菊》第一，《問菊》第二，《菊夢》第三，題目新，詩也新，立意更新，惱不得要推瀟湘妃子為魁了」三首都是黛玉的。她的《咏菊》里有「口齿噙香对月吟」「一从陶令平章后」。十二首菊花诗，前三名都是潇湘妃子的。上回海棠社宝钗夺魁，这回还了过来，李纨评诗一碗水端平。","place":"ouxiang","hui":[38],"img":{"full":"dgy-assets/huace/img/chixie-04.webp","thumb":"dgy-assets/huace/img/chixie-04-s.webp"},"画面":"榭里窗边，李纨手拿誊清的诗稿，笑着当众评：“《咏菊》第一，《问菊》第二，《菊梦》第三”；黛玉低头抿嘴，宝玉拍手叫好。","quote":{"文":"今日公評：《詠菊》第一，《問菊》第二，《菊夢》第三，題目新，詩也新，立意更新，惱不得要推瀟湘妃子為魁了","回":38}},"chixie:5":{"n":"藕香榭持螯赏桂·第5幅","t":"藕香榭","册":"chixie","幅":5,"line":"「眼前道路無經緯，皮裡春秋空黑黃。」众人说这是食螃蟹绝唱，又说讽刺世人太毒了些。宝玉说：“写得痛快！我的诗也该烧了。”宝钗素日最是浑厚，一提笔写螃蟹，倒骂得最狠。可知她不是不会刁，是不肯。","place":"ouxiang","hui":[38],"img":{"full":"dgy-assets/huace/img/chixie-05.webp","thumb":"dgy-assets/huace/img/chixie-05-s.webp"},"画面":"又要了热蟹，大圆桌上再吃。宝钗提笔写完，放下笔；宝玉凑过来看，拍手；黛玉在旁抿嘴笑。","quote":{"文":"眼前道路無經緯，皮裡春秋空黑黃。","回":38}},"baiyue:1":{"n":"嘉荫堂拜月·第1幅","t":"嘉荫堂","册":"baiyue","幅":1,"line":"「當下園之正門俱已大開，吊著羊角大燈。嘉蔭堂前月臺上，焚著斗香，秉著風燭，陳獻著瓜餅及各色果品。邢夫人等一干女客皆在裡面久候。」这是中秋拜月的香案，不是日常陈设。前一回才抄检过这园子，今夜园门又大开，羊角灯高高吊起。香案摆得越齐，越见得人心不齐。","place":"jiayin","hui":[75],"img":{"full":"dgy-assets/huace/img/baiyue-01.webp","thumb":"dgy-assets/huace/img/baiyue-01-s.webp"},"画面":"月夜，嘉荫堂前的月台。园门大开，门上吊着羊角大灯；月台上焚着斗香，风烛点着，案上摆着瓜饼和各色果品；堂内女客们在窗内等候。月亮用纸色留白。","quote":{"文":"當下園之正門俱已大開，吊著羊角大燈。嘉蔭堂前月臺上，焚著斗香，秉著風燭，陳獻著瓜餅及各色果品。邢夫人等一干女客皆在裡面久候。","回":75}},"baiyue:2":{"n":"嘉荫堂拜月·第2幅","t":"嘉荫堂","册":"baiyue","幅":2,"line":"「真是月明燈彩，人氣香煙，晶艷氤氳，不可形狀。地下舖著拜毯錦褥。」贾母是在荣府说了“此时月已上了，咱们且去上香”，扶着宝玉的肩带众人入园的。满园的人跟着，老太太手里扶的只是宝玉。一家的指望，她也是这样扶着走的。","place":"jiayin","hui":[75],"img":{"full":"dgy-assets/huace/img/baiyue-02.webp","thumb":"dgy-assets/huace/img/baiyue-02-s.webp"},"画面":"月明灯彩，香烟缭绕。地上铺着拜毯和锦褥。贾母一手扶着宝玉的肩，走上月台；众人在后跟随。","quote":{"文":"真是月明燈彩，人氣香煙，晶艷氤氳，不可形狀。地下舖著拜毯錦褥。","回":75}},"baiyue:3":{"n":"嘉荫堂拜月·第3幅","t":"嘉荫堂","册":"baiyue","幅":3,"line":"「賈母盥手上香拜畢，於是大家皆拜過。」拜完她才说，赏月在山上最好。一拜下去，月台上背影成排。人数看着齐，薛家姊妹已经搬出去了，不在里头。","place":"jiayin","hui":[75],"img":{"full":"dgy-assets/huace/img/baiyue-03.webp","thumb":"dgy-assets/huace/img/baiyue-03-s.webp"},"画面":"贾母盥过手，在月台上香，拜下去；后面女眷们跟着拜，背影成排。","quote":{"文":"賈母盥手上香拜畢，於是大家皆拜過。","回":75}},"baiyue:4":{"n":"嘉荫堂拜月·第4幅","t":"嘉荫堂","册":"baiyue","幅":4,"line":"「賈母便說：「賞月在山上最好。」因命在那山脊上的大廳上去。眾人聽說，就忙著在那裡去舖設。賈母且在嘉蔭堂中吃茶少歇，說些閒話。」人回“都齐备了”，她才扶着人上山。上山之前，先吃一盏茶，说几句闲话。老太太的排场不在灯多，在不急。","place":"jiayin","hui":[75],"img":{"full":"dgy-assets/huace/img/baiyue-04.webp","thumb":"dgy-assets/huace/img/baiyue-04-s.webp"},"画面":"堂内，贾母坐下吃茶，和人说着闲话，等山上铺设好；鸳鸯琥珀在旁伺候；窗外是月色。","quote":{"文":"賈母便說：「賞月在山上最好。」因命在那山脊上的大廳上去。眾人聽說，就忙著在那裡去舖設。賈母且在嘉蔭堂中吃茶少歇，說些閒話。","回":75}},"baiyue:5":{"n":"嘉荫堂拜月·第5幅","t":"嘉荫堂","册":"baiyue","幅":5,"line":"「一時，人回：「都齊備了。」賈母方扶著人上山來。王夫人等因說：「恐石上苔滑，還是坐竹椅上去。」賈母道：「天天有人打掃，況且極平穩的寬路，何必不疏散疏散筋骨。」」王夫人怕石上苔滑，要她坐竹椅；贾母说路平稳、天天有人打扫。这条路通往下一册的凸碧山庄。不坐竹椅，要疏散筋骨，是不肯认老。这一夜她到底还是叹了人少，掉了泪。","place":"jiayin","hui":[75],"img":{"full":"dgy-assets/huace/img/baiyue-05.webp","thumb":"dgy-assets/huace/img/baiyue-05-s.webp"},"画面":"夜路上山：贾赦、贾政在前面引路，两个老婆子各举一盏羊角手罩，鸳鸯、琥珀、尤氏贴身搀扶着贾母，邢夫人等在后跟随；贾母摆手不坐竹椅。","quote":{"文":"一時，人回：「都齊備了。」賈母方扶著人上山來。王夫人等因說：「恐石上苔滑，還是坐竹椅上去。」賈母道：「天天有人打掃，況且極平穩的寬路，何必不疏散疏散筋骨。」","回":75}},"zhongqiu:1":{"n":"凸碧山庄中秋·第1幅","t":"凸碧山庄","册":"zhongqiu","幅":1,"line":"「從下逶迤而上，不過百餘步，至山之峰脊上，便是這座敞廳。因在山之高脊，故名曰凸碧山莊。於廳前平臺上列下桌椅，又用一架大圍屏隔作兩間。凡桌椅形式皆是圓的，特取團圓之意。」山路逶迤百余步到脊上，所以叫凸碧山庄。桌椅全是圆的，取团圆之意。桌椅件件取团圆，下一幅便坐不满半壁。东西是圆的，人是缺的。","place":"tubi","hui":[75],"img":{"full":"dgy-assets/huace/img/zhongqiu-01.webp","thumb":"dgy-assets/huace/img/zhongqiu-01-s.webp"},"画面":"夜里，山脊上一座敞厅，厅前平台上摆满圆桌圆椅，一架大围屏把平台隔成两间；灯笼点着，月在山脊上方，纸色留白。桌上还没有人落座。","quote":{"文":"從下逶迤而上，不過百餘步，至山之峰脊上，便是這座敞廳。因在山之高脊，故名曰凸碧山莊。於廳前平臺上列下桌椅，又用一架大圍屏隔作兩間。凡桌椅形式皆是圓的，特取團圓之意。","回":75}},"zhongqiu:2":{"n":"凸碧山庄中秋·第2幅","t":"凸碧山庄","册":"zhongqiu","幅":2,"line":"「賈母便命折一枝桂花來，命一媳婦在屏後擊鼓傳花。若花到誰手中，飲酒一杯，罰說笑話一個。」先从贾母传起。圆桌只坐了半壁，贾母说“今日就这样，太少了”。一枝桂花在一家子手里转，花停在谁手里，谁就得说笑话。长辈们这一夜也要轮着给老太太凑趣。","place":"tubi","hui":[75],"img":{"full":"dgy-assets/huace/img/zhongqiu-02.webp","thumb":"dgy-assets/huace/img/zhongqiu-02-s.webp"},"画面":"圆桌围坐：贾母居中，左边贾赦、贾珍、贾琏、贾蓉，右边贾政、宝玉、贾环、贾兰；围屏后面露出一个媳妇的半个身影，手里敲着鼓，桌上一枝桂花在传。","quote":{"文":"賈母便命折一枝桂花來，命一媳婦在屏後擊鼓傳花。若花到誰手中，飲酒一杯，罰說笑話一個。","回":75}},"zhongqiu:3":{"n":"凸碧山庄中秋·第3幅","t":"凸碧山庄","册":"zhongqiu","幅":3,"line":"「鼓聲兩轉，恰恰在賈政手中住了，只得飲了酒。眾姊妹弟兄皆你悄悄的扯我一下，我暗暗的又捏你一把，都含笑倒要聽是何笑話。賈政見賈母喜悅，只得承歡。方欲說時，賈母又笑道：「若說的不笑了，還要罰。」賈政笑道：「只得一個，說來不笑，也只好受罰了。」因笑道：「一家子一個人最怕老婆的。」才說了一句，大家都笑了。」大家笑，是因为从没听贾政说过笑话。笑话的后文不画。从来板着脸的人，开口头一句是怕老婆，满座先笑了。不是笑话好笑，是说笑话的人好笑。","place":"tubi","hui":[75],"img":{"full":"dgy-assets/huace/img/zhongqiu-03.webp","thumb":"dgy-assets/huace/img/zhongqiu-03-s.webp"},"画面":"鼓停了，桂花正在贾政手里。他举杯喝酒，开口说话，满座已经憋不住笑；贾母看着他，等下文。","quote":{"文":"鼓聲兩轉，恰恰在賈政手中住了，只得飲了酒。眾姊妹弟兄皆你悄悄的扯我一下，我暗暗的又捏你一把，都含笑倒要聽是何笑話。賈政見賈母喜悅，只得承歡。方欲說時，賈母又笑道：「若說的不笑了，還要罰。」賈政笑道：「只得一個，說來不笑，也只好受罰了。」因笑道：「一家子一個人最怕老婆的。」才說了一句，大家都笑了。","回":75}},"zhongqiu:4":{"n":"凸碧山庄中秋·第4幅","t":"凸碧山庄","册":"zhongqiu","幅":4,"line":"「賈母因見月至中天，比先越發精彩可愛，因說：「如此好月，不可不聞笛。」因命人將十番上女孩子傳來。賈母道：「音樂多了，反失雅致，只用吹笛的遠遠的吹起來就夠了。」」贾母的意思是：音乐多了反失雅致，只要一支笛子远远地吹。热闹到这里该收了，老太太只留一支笛，还要远远的。她不知道，越远越凄凉。","place":"tubi","hui":[76],"img":{"full":"dgy-assets/huace/img/zhongqiu-04.webp","thumb":"dgy-assets/huace/img/zhongqiu-04-s.webp"},"画面":"月亮到了中天。贾母笑着抬手吩咐，要远远地吹笛；一个婆子应声退下去传话的背影。桂花树下隐约有人。","quote":{"文":"賈母因見月至中天，比先越發精彩可愛，因說：「如此好月，不可不聞笛。」因命人將十番上女孩子傳來。賈母道：「音樂多了，反失雅致，只用吹笛的遠遠的吹起來就夠了。」","回":76}},"zhongqiu:5":{"n":"凸碧山庄中秋·第5幅","t":"凸碧山庄","册":"zhongqiu","幅":5,"line":"「只聽桂花陰裡，嗚嗚咽咽，裊裊悠悠，又發出一縷笛音來，果真比先越發淒涼。大家都寂然而坐。夜靜月明，且笛聲悲怨，賈母年老帶酒之人，聽此聲音，不免有觸於心，禁不住墮下淚來。」回目「凸碧堂品笛感凄清」说的就是这里。老太太一辈子在热闹堆里，这一夜被一支笛子说哭了。王夫人尤氏陪笑解劝，是这席上最难的差事。","place":"tubi","hui":[76],"img":{"full":"dgy-assets/huace/img/zhongqiu-05.webp","thumb":"dgy-assets/huace/img/zhongqiu-05-s.webp"},"画面":"笛声从桂花树下传来，席上的人都静静坐着。贾母戴着兜巾、披着大斗篷，眼里掉下泪来，抬手拭泪；王夫人、尤氏在旁陪笑解劝。桂花树下一个极小的吹笛人影。","quote":{"文":"只聽桂花陰裡，嗚嗚咽咽，裊裊悠悠，又發出一縷笛音來，果真比先越發淒涼。大家都寂然而坐。夜靜月明，且笛聲悲怨，賈母年老帶酒之人，聽此聲音，不免有觸於心，禁不住墮下淚來。","回":76}},"zhongqiu:6":{"n":"凸碧山庄中秋·第6幅","t":"凸碧山庄","册":"zhongqiu","幅":6,"line":"「原來黛玉和湘雲二人並未去睡覺。只因黛玉見賈府中許多人賞月，賈母猶歎人少，不似當年熱鬧，又提寶釵姊妹家去母女弟兄自去賞月等語，不覺對景感懷，自去俯欄垂淚。」她嫌山上人声嘈杂，觉得没有诗兴；随后和湘云下山去凹晶溪馆联诗，那一段在「凹晶馆联诗」册。席上叹人少，人人陪笑，只有栏边两个没笑。黛玉湘云，都是没了爹娘、寄在这府里的人。","place":"tubi","hui":[76],"img":{"full":"dgy-assets/huace/img/zhongqiu-06.webp","thumb":"dgy-assets/huace/img/zhongqiu-06-s.webp"},"画面":"敞厅一角的栏杆边，黛玉双手扶栏，低头垂泪；湘云站在她身旁，侧身劝她；远处席上灯火、人影。","quote":{"文":"原來黛玉和湘雲二人並未去睡覺。只因黛玉見賈府中許多人賞月，賈母猶歎人少，不似當年熱鬧，又提寶釵姊妹家去母女弟兄自去賞月等語，不覺對景感懷，自去俯欄垂淚。","回":76}},"huaqiang:1":{"n":"龄官画蔷·第1幅","t":"花圃","册":"huaqiang","幅":1,"line":"「剛到了薔薇花架，只聽有人哽噎之聲。寶玉心中疑惑，便站住細聽，果然架下那邊有人。」他刚从王夫人屋里出来，自己进的大观园。他是刚闯了金钏的祸，一溜烟躲进园来的。一肚子闷，一转身撞见了别人的伤心。","place":"flowers","hui":[30],"img":{"full":"dgy-assets/huace/img/huaqiang-01.webp","thumb":"dgy-assets/huace/img/huaqiang-01-s.webp"},"画面":"五月正午，赤日当空，树荫合地，蔷薇花架叶子茂盛成片。宝玉从园径走来，停步，侧耳；架子那边有哽咽声，看不见脸。","quote":{"文":"剛到了薔薇花架，只聽有人哽噎之聲。寶玉心中疑惑，便站住細聽，果然架下那邊有人。","回":30}},"huaqiang:2":{"n":"龄官画蔷·第2幅","t":"花圃","册":"huaqiang","幅":2,"line":"「寶玉便悄悄的隔著籬笆洞兒一看，只見一個女孩子蹲在花下，手裡拿著根綰頭的簪子在地下摳土，一面悄悄的流淚」他先以为是又一个黛玉来葬花，看清了不是身边的丫头，像是学戏的女孩子。宝玉头一个念头是「又象顰兒來葬花」。园里的痴人他一个个都认得，只这一个不认得。","place":"flowers","hui":[30],"img":{"full":"dgy-assets/huace/img/huaqiang-02.webp","thumb":"dgy-assets/huace/img/huaqiang-02-s.webp"},"画面":"从篱笆洞外往里看：一个女孩子蹲在花下，手里一根绾头的簪子在地上抠土，一面无声地哭。宝玉隔着花叶看，只露半边脸。","quote":{"文":"寶玉便悄悄的隔著籬笆洞兒一看，只見一個女孩子蹲在花下，手裡拿著根綰頭的簪子在地下摳土，一面悄悄的流淚","回":30}},"huaqiang:3":{"n":"龄官画蔷·第3幅","t":"花圃","册":"huaqiang","幅":3,"line":"「只見他雖然用金簪劃地，並不是掘土埋花，竟是向土上畫字。寶玉用眼隨著簪子的起落，一直一畫一點一勾的看了去，數一數，十八筆。自己又在手心裡用指頭按著他方才下筆的規矩寫了，猜是個什麼字。寫成一想，原來就是個薔薇花的「薔」字。」回目作「龄官划蔷」。她用金簪划地，不是掘土埋花。十八笔一个蔷字，他在手心里描了一遍，只想到蔷薇花上去。园里叫蔷的，不止一架花。","place":"flowers","hui":[30],"img":{"full":"dgy-assets/huace/img/huaqiang-03.webp","thumb":"dgy-assets/huace/img/huaqiang-03-s.webp"},"画面":"地上不是坑，是字。女孩子用金簪一笔一画地划；花外，宝玉用手指在手心里跟着写，眼睛随着簪子走。","quote":{"文":"只見他雖然用金簪劃地，並不是掘土埋花，竟是向土上畫字。寶玉用眼隨著簪子的起落，一直一畫一點一勾的看了去，數一數，十八筆。自己又在手心裡用指頭按著他方才下筆的規矩寫了，猜是個什麼字。寫成一想，原來就是個薔薇花的「薔」字。","回":30}},"huaqiang:4":{"n":"龄官画蔷·第4幅","t":"花圃","册":"huaqiang","幅":4,"line":"「畫來畫去，還是個「薔」字。再看，還是個「薔」字。裡面的原是早已痴了，畫完一個又畫一個，已經畫了有幾千個「薔」。外面的不覺也看痴了，兩個眼睛珠兒只管隨著簪子動」她写了有几千个，写完一个又是一个。他看痴了，还当这份痴总与自己相干。到第三十六回才认了：「各人各得眼淚」（第36回）。","place":"flowers","hui":[30],"img":{"full":"dgy-assets/huace/img/huaqiang-04.webp","thumb":"dgy-assets/huace/img/huaqiang-04-s.webp"},"画面":"地上已是一串密密的字痕。女孩子还在写下一个；宝玉在花外看痴了，眼睛只跟着簪子走。","quote":{"文":"畫來畫去，還是個「薔」字。再看，還是個「薔」字。裡面的原是早已痴了，畫完一個又畫一個，已經畫了有幾千個「薔」。外面的不覺也看痴了，兩個眼睛珠兒只管隨著簪子動","回":30}},"huaqiang:5":{"n":"龄官画蔷·第5幅","t":"花圃","册":"huaqiang","幅":5,"line":"「那女孩子聽說倒唬了一跳，抬頭一看，只見花外一個人叫他不要寫了，下大雨了。一則寶玉臉面俊秀，二則花葉繁茂，上下俱被枝葉隱住，剛露著半邊臉，那女孩子只當是個丫頭，再不想是寶玉，因笑道：「多謝姐姐提醒了我。難道姐姐在外頭有什麼遮雨的？」」宝玉这才觉得自己也湿透了，一气跑回怡红院，心里还记挂着她没处避雨。她把宝玉当丫头，宝玉也忘了自己是宝玉，只顾替人愁雨。跑回怡红院叫门，袭人倒挨了一脚。","place":"flowers","hui":[30],"img":{"full":"dgy-assets/huace/img/huaqiang-05.webp","thumb":"dgy-assets/huace/img/huaqiang-05-s.webp"},"画面":"一阵骤雨。女孩子纱衣湿透，头上往下滴水；花外只露出宝玉半边脸，他叫她别写了。她抬头，把他当成丫头，笑着说多谢姐姐。","quote":{"文":"那女孩子聽說倒唬了一跳，抬頭一看，只見花外一個人叫他不要寫了，下大雨了。一則寶玉臉面俊秀，二則花葉繁茂，上下俱被枝葉隱住，剛露著半邊臉，那女孩子只當是個丫頭，再不想是寶玉，因笑道：「多謝姐姐提醒了我。難道姐姐在外頭有什麼遮雨的？」","回":30}},"xuedong:1":{"n":"蘅芜苑雪洞·第1幅","t":"蘅芜苑","册":"xuedong","幅":1,"line":"「賈母因見岸上的清廈曠朗，便問：「這是你薛姑娘的屋子不是？」眾人道：「是。」賈母忙命攏岸，順著雲步石梯上去，一同進了蘅蕪苑，只覺異香撲鼻。那些奇草仙藤愈冷逾蒼翠，都結了實，似珊瑚豆子一般，累垂可愛。」第十七回这里没有一株花木，只有香草。秋天结了实。满院不种花，只有香草，越冷越苍翠。这院子的主人，吃的是「冷香丸」（第7回）。","place":"hengwu","hui":[40],"img":{"full":"dgy-assets/huace/img/xuedong-01.webp","thumb":"dgy-assets/huace/img/xuedong-01-s.webp"},"画面":"白天，贾母沿着云步石梯上岸进院，鸳鸯搀着，王夫人、薛姨妈在后；院里奇草仙藤结了实，像一串串珊瑚豆子垂下来。","quote":{"文":"賈母因見岸上的清廈曠朗，便問：「這是你薛姑娘的屋子不是？」眾人道：「是。」賈母忙命攏岸，順著雲步石梯上去，一同進了蘅蕪苑，只覺異香撲鼻。那些奇草仙藤愈冷逾蒼翠，都結了實，似珊瑚豆子一般，累垂可愛。","回":40}},"xuedong:2":{"n":"蘅芜苑雪洞·第2幅","t":"蘅芜苑","册":"xuedong","幅":2,"line":"「及進了房屋，雪洞一般，一色玩器全無，案上只有一個土定瓶中供著數枝菊花，並兩部書，茶奩茶杯而已。床上只吊著青紗帳幔，衾褥也十分樸素。」玩器一样没有。贾母进门先叹。这间屋素得像没人住。宝钗是真不要，还是不肯要，书里不说，只让贾母叹了一口气。","place":"hengwu","hui":[40],"img":{"full":"dgy-assets/huace/img/xuedong-02.webp","thumb":"dgy-assets/huace/img/xuedong-02-s.webp"},"画面":"屋里空得像雪洞：案上只有一只土定瓶，插着几枝菊花，两部书，茶奁茶杯；床上青纱帐，被褥素朴。贾母站在门口，抬手叹气，没有人坐。","quote":{"文":"及進了房屋，雪洞一般，一色玩器全無，案上只有一個土定瓶中供著數枝菊花，並兩部書，茶奩茶杯而已。床上只吊著青紗帳幔，衾褥也十分樸素。","回":40}},"xuedong:3":{"n":"蘅芜苑雪洞·第3幅","t":"蘅芜苑","册":"xuedong","幅":3,"line":"「賈母歎道：「這孩子太老實了。你沒有陳設，何妨和你姨娘要些。我也不理論，也沒想到，你們的東西自然在家裡沒帶了來。」說著，命鴛鴦去取些古董來，又嗔著鳳姐兒：「不送些玩器來與你妹妹，這樣小器。」王夫人鳳姐兒等都笑回說：「他自己不要的。我們原送了來，他都退回去了。」薛姨媽也笑說：「他在家裡也不大弄這些東西的。」賈母搖頭說：「使不得。雖然他省事，倘或來一個親戚，看著不象，二則年輕的姑娘們，房裡這樣素淨，也忌諱。我們這老婆子，越發該住馬圈去了。」东西送来过，宝钗自己退回去了。贾母的意思是：年轻姑娘屋里这么素净，忌讳；她这种老婆子倒该去住马圈了。贾母说忌讳，是老人家的直觉。雪洞一般的屋子，读到后来，竟像宝钗一生的影子。","place":"hengwu","hui":[40],"img":{"full":"dgy-assets/huace/img/xuedong-03.webp","thumb":"dgy-assets/huace/img/xuedong-03-s.webp"},"画面":"贾母站着说话，一手指着空案，另一手指向凤姐，嗔怪；凤姐、王夫人笑着回话，薛姨妈也笑着摆手。","quote":{"文":"賈母歎道：「這孩子太老實了。你沒有陳設，何妨和你姨娘要些。我也不理論，也沒想到，你們的東西自然在家裡沒帶了來。」說著，命鴛鴦去取些古董來，又嗔著鳳姐兒：「不送些玩器來與你妹妹，這樣小器。」王夫人鳳姐兒等都笑回說：「他自己不要的。我們原送了來，他都退回去了。」薛姨媽也笑說：「他在家裡也不大弄這些東西的。」賈母搖頭說：「使不得。雖然他省事，倘或來一個親戚，看著不象，二則年輕的姑娘們，房裡這樣素淨，也忌諱。我們這老婆子，越發該住馬圈去了。","回":40}},"xuedong:4":{"n":"蘅芜苑雪洞·第4幅","t":"蘅芜苑","册":"xuedong","幅":4,"line":"「說著叫過鴛鴦來，親吩咐道：「你把那石頭盆景兒和那架紗桌屏，還有個墨煙凍石鼎，這三樣擺在這案上就夠了。再把那水墨字畫白綾帳子拿來，把這帳子也換了。」」东西在东楼上的箱子里，鸳鸯说得慢慢找，明日再拿；贾母说“别忘了”。三样东西，素里添雅，不添俗。老太太自夸「最會收拾屋子」，这间屋到她手里才算收拾完。","place":"hengwu","hui":[40],"img":{"full":"dgy-assets/huace/img/xuedong-04.webp","thumb":"dgy-assets/huace/img/xuedong-04-s.webp"},"画面":"贾母叫过鸳鸯，伸出三根手指吩咐：石头盆景、纱桌屏、墨烟冻石鼎，摆到案上；再拿水墨字画的白绫帐子把青纱帐换了；鸳鸯笑着点头。","quote":{"文":"說著叫過鴛鴦來，親吩咐道：「你把那石頭盆景兒和那架紗桌屏，還有個墨煙凍石鼎，這三樣擺在這案上就夠了。再把那水墨字畫白綾帳子拿來，把這帳子也換了。」","回":40}},"shengqin:1":{"n":"元妃省亲·第1幅","t":"省亲别墅","册":"shengqin","幅":1,"line":"「一時，舟臨內岸，復棄舟上輿，便見琳宮綽約，桂殿巍峨。石牌坊上明顯「天仙寶境」四字，賈妃忙命換「省親別墅」四字。」牌坊在行宫前面。刘姥姥后来把这里认成「玉皇宝殿」，是第四十一回，已在游园册。她把天仙宝境换成省亲别墅，自己先降了一等：这园子不是仙境，是回娘家。","place":"xingqin","hui":[18],"img":{"full":"dgy-assets/huace/img/shengqin-01.webp","thumb":"dgy-assets/huace/img/shengqin-01-s.webp"},"画面":"夜里，船靠内岸，元春弃舟上舆，抬舆太监两旁；前方一座玉石牌坊，上面龙蟠螭护、玲珑凿就，匾面空白（不画字）。元春在舆中抬手吩咐。","quote":{"文":"一時，舟臨內岸，復棄舟上輿，便見琳宮綽約，桂殿巍峨。石牌坊上明顯「天仙寶境」四字，賈妃忙命換「省親別墅」四字。","回":18}},"shengqin:2":{"n":"元妃省亲·第2幅","t":"省亲别墅","册":"shengqin","幅":2,"line":"「於是進入行宮。但見庭燎燒空，香屑布地，火樹琪花，金窗玉檻。說不盡簾卷蝦須，毯舖魚獺，鼎飄麝腦之香，屏列雉尾之扇。」第十七回贾政觉得正殿太富丽，清客说贵妃的礼仪应当这样。满眼金玉，贵妃在轿内看了，只「默默歎息奢華過費」。这一家子的银子，最心疼的倒是宫里回来的人。","place":"xingqin","hui":[18],"img":{"full":"dgy-assets/huace/img/shengqin-02.webp","thumb":"dgy-assets/huace/img/shengqin-02-s.webp"},"画面":"进了行宫：庭燎烧得高过屋檐，香屑铺满地面；火树琪花，金窗玉槛；帘子卷着如虾须，地毯如鱼獭皮，鼎里麝香，屏上雉尾扇。无人，或极小的太监背影。","quote":{"文":"於是進入行宮。但見庭燎燒空，香屑布地，火樹琪花，金窗玉檻。說不盡簾卷蝦須，毯舖魚獺，鼎飄麝腦之香，屏列雉尾之扇。","回":18}},"shengqin:3":{"n":"元妃省亲·第3幅","t":"省亲别墅","册":"shengqin","幅":3,"line":"「賈妃乃問：「此殿何無匾額？」隨侍太監跪啟曰：「此係正殿，外臣未敢擅擬。」賈妃點頭不語。禮儀太監跪請升座受禮，兩陛樂起。禮儀太監二人引賈赦，賈政等於月臺下排班，殿上昭容傳諭曰：「免。」太監引賈赦等退出。」殿上传谕“免”，行礼的人退出。女眷从东阶上来，也免了。园子再大，最当中一处正殿要留给天家。父亲排班在月台下，一个免字传下来，父女之间就隔着这道台阶。","place":"xingqin","hui":[18],"img":{"full":"dgy-assets/huace/img/shengqin-03.webp","thumb":"dgy-assets/huace/img/shengqin-03-s.webp"},"画面":"正殿月台前：元春升座，昭容抬手传谕；太监跪着；贾赦、贾政在月台下排班退出；两边乐队奏乐。殿上没有匾，匾位空白。","quote":{"文":"賈妃乃問：「此殿何無匾額？」隨侍太監跪啟曰：「此係正殿，外臣未敢擅擬。」賈妃點頭不語。禮儀太監跪請升座受禮，兩陛樂起。禮儀太監二人引賈赦，賈政等於月臺下排班，殿上昭容傳諭曰：「免。」太監引賈赦等退出。","回":18}},"shengqin:4":{"n":"元妃省亲·第4幅","t":"省亲别墅","册":"shengqin","幅":4,"line":"「元妃乃命傳筆硯伺候，親搦湘管，擇其幾處最喜者賜名。」这一回赐的名字有：大观园，有凤来仪→潇湘馆，红香绿玉→怡红快绿即怡红院，蘅芷清芬→蘅芜苑，杏帘在望→浣葛山庄（后改稻香村）。旧匾都不摘。旧匾一块不摘，又另赐新名，两样都不废。贾政骂过的胡说，如今都成了御笔留下的。","place":"xingqin","hui":[18],"img":{"full":"dgy-assets/huace/img/shengqin-04.webp","thumb":"dgy-assets/huace/img/shengqin-04-s.webp"},"画面":"元春坐在案前，亲自提笔蘸墨，要给几处最喜欢的地方赐名；宝玉、姐妹们站在案侧垂手听。","quote":{"文":"元妃乃命傳筆硯伺候，親搦湘管，擇其幾處最喜者賜名。","回":18}},"shengqin:5":{"n":"元妃省亲·第5幅","t":"省亲别墅","册":"shengqin","幅":5,"line":"「寶釵轉眼瞥見，便趁眾人不理論，急忙回身悄推他道：「他因不喜『紅香綠玉』四字，改了『怡紅快綠』，你這會子偏用『綠玉』二字，豈不是有意和他爭馳了？況且蕉葉之說也頗多，再想一個字改了罷。」寶玉見寶釵如此說，便拭汗道：「我這會子總想不起什麼典故出處來。」寶釵笑道：「你只把『綠玉』的『玉』字改作『蠟』字就是了。」」宝玉写“绿玉春犹卷”，宝钗怕他和元春改的“怡红快绿”相冲，提醒他改“绿蜡”，出处是钱珝咏芭蕉。他笑称她“一字师”。宝钗教了一个字，又堵他一句「那上頭穿黃袍的才是你姐姐」。尊卑那根弦，她从来不松。","place":"xingqin","hui":[18],"img":{"full":"dgy-assets/huace/img/shengqin-05.webp","thumb":"dgy-assets/huace/img/shengqin-05-s.webp"},"画面":"殿内一角的案前，宝玉提笔出汗；宝钗趁人不注意侧身凑近，悄悄推他一下，低声指点；远处元春端坐，模糊，不要求认脸。","quote":{"文":"寶釵轉眼瞥見，便趁眾人不理論，急忙回身悄推他道：「他因不喜『紅香綠玉』四字，改了『怡紅快綠』，你這會子偏用『綠玉』二字，豈不是有意和他爭馳了？況且蕉葉之說也頗多，再想一個字改了罷。」寶玉見寶釵如此說，便拭汗道：「我這會子總想不起什麼典故出處來。」寶釵笑道：「你只把『綠玉』的『玉』字改作『蠟』字就是了。」","回":18}},"shengqin:6":{"n":"元妃省亲·第6幅","t":"省亲别墅","册":"shengqin","幅":6,"line":"「說畢，低頭一想，早已吟成一律，便寫在紙條上，搓成個團子，擲在他跟前。寶玉打開一看，只覺此首比自己所作的三首高過十倍，真是喜出望外，遂忙恭楷呈上。」这就是《杏帘在望》那首。元春评它为前三首之冠，把「浣葛山庄」改称「稻香村」。黛玉本打算今夜「大展奇才」，贵妃只命一匾一咏，满腹才情没处使，便替宝玉捉了刀。","place":"xingqin","hui":[18],"img":{"full":"dgy-assets/huace/img/shengqin-06.webp","thumb":"dgy-assets/huace/img/shengqin-06-s.webp"},"画面":"黛玉走到宝玉案旁，手一扬，把一个纸团扔在他面前的案上；宝玉低头打开，满脸惊喜。","quote":{"文":"說畢，低頭一想，早已吟成一律，便寫在紙條上，搓成個團子，擲在他跟前。寶玉打開一看，只覺此首比自己所作的三首高過十倍，真是喜出望外，遂忙恭楷呈上。","回":18}},"yeyan:1":{"n":"寿怡红群芳开夜宴·第1幅","t":"怡红院","册":"yeyan","幅":1,"line":"「先後都到了怡紅院中。襲人又死活拉了香菱來。炕上又並了一張桌子，方坐開了。寶玉忙說：「林妹妹怕冷，過這邊靠板壁坐。」又拿個靠背墊著些。」袭人本来怕巡夜的听见。探春也吃酒，宝玉说把她也请了来。席上人最多的一夜，宝玉手里头一件忙的，是给林妹妹垫一个靠背。","place":"yihong","hui":[63],"img":{"full":"dgy-assets/huace/img/yeyan-01.webp","thumb":"dgy-assets/huace/img/yeyan-01-s.webp"},"画面":"夜里，怡红院宝玉屋里炕上又并了一张桌子，各色小碟摆满；宝钗、李纨、探春、宝琴、香菱先后坐下；宝玉让黛玉靠板壁坐，亲手给她垫上靠背，黛玉离桌稍远，笑着靠着。","quote":{"文":"先後都到了怡紅院中。襲人又死活拉了香菱來。炕上又並了一張桌子，方坐開了。寶玉忙說：「林妹妹怕冷，過這邊靠板壁坐。」又拿個靠背墊著些。","回":63}},"yeyan:2":{"n":"寿怡红群芳开夜宴·第2幅","t":"怡红院","册":"yeyan","幅":2,"line":"「寶玉道：「沒趣，不好。咱們占花名兒好。」晴雯笑道：「正是早已想弄這個頑意兒。」」人少了没趣，所以把园里的姐妹都拉了来。这一席是丫头们每人五钱银子凑的。丫头做东，小姐赴席，园里的尊卑只在这一夜松了一松。","place":"yihong","hui":[63],"img":{"full":"dgy-assets/huace/img/yeyan-02.webp","thumb":"dgy-assets/huace/img/yeyan-02-s.webp"},"画面":"炕桌上酒果齐备；晴雯笑着拿来一个竹雕签筒，里面装着象牙花名签子；宝玉在旁拍手；袭人、麝月、芳官围坐。","quote":{"文":"寶玉道：「沒趣，不好。咱們占花名兒好。」晴雯笑道：「正是早已想弄這個頑意兒。」","回":63}},"yeyan:3":{"n":"寿怡红群芳开夜宴·第3幅","t":"怡红院","册":"yeyan","幅":3,"line":"「簽上畫著一支牡丹，題著「艷冠群芳」四字，下面又有鐫的小字一句唐詩，道是：任是無情也動人。」注说此为群芳之冠，在席共贺一杯。芳官接着唱《赏花时》，被众人喝住，另唱。牡丹配宝钗，众人都服。签上那句诗，众人只顾贺酒，宝玉却拿着签颠来倒去地念。","place":"yihong","hui":[63],"img":{"full":"dgy-assets/huace/img/yeyan-03.webp","thumb":"dgy-assets/huace/img/yeyan-03-s.webp"},"画面":"宝钗掣出一根签，举起给众人看：签上画着一枝牡丹（只画牡丹，不画字）；众人笑着举杯共贺；宝玉在旁出神地看着。","quote":{"文":"簽上畫著一支牡丹，題著「艷冠群芳」四字，下面又有鐫的小字一句唐詩，道是：任是無情也動人。","回":63}},"yeyan:4":{"n":"寿怡红群芳开夜宴·第4幅","t":"怡红院","册":"yeyan","幅":4,"line":"「只恐夜深花睡去。黛玉笑道：「『夜深』兩個字，改『石涼』兩個字。」」黛玉把“夜深”改成“石凉”，众人知道她在说白天湘云醉卧芍药裀。注说掣到的人不能饮酒，由上下家代喝：黛玉把酒倒进漱盂，宝玉偷偷递给芳官。黛玉一改两字，众人便想起白天芍药裀。偏是园里最爱喝的一个，掣了个不便饮酒的签。","place":"yihong","hui":[63],"img":{"full":"dgy-assets/huace/img/yeyan-04.webp","thumb":"dgy-assets/huace/img/yeyan-04-s.webp"},"画面":"湘云揎拳捋袖，掣出一根签，上面画着一枝海棠（只画花）；黛玉笑着指她；湘云拍手大笑，说这签好。","quote":{"文":"只恐夜深花睡去。黛玉笑道：「『夜深』兩個字，改『石涼』兩個字。」","回":63}},"yeyan:5":{"n":"寿怡红群芳开夜宴·第5幅","t":"怡红院","册":"yeyan","幅":5,"line":"「只見上面畫著一枝芙蓉，題著「風露清愁」四字，那面一句舊詩，道是：莫怨東風當自嗟。」注是：自饮一杯，牡丹（宝钗）陪饮一杯。众人说只有她配芙蓉。第七十八回宝玉祭晴雯，作的也是芙蓉诔，芙蓉二字，一花两人（第78回）。","place":"yihong","hui":[63],"img":{"full":"dgy-assets/huace/img/yeyan-05.webp","thumb":"dgy-assets/huace/img/yeyan-05-s.webp"},"画面":"黛玉抽到一枝芙蓉的签（只画花），自己也笑了；宝钗举杯，众人笑着说除了黛玉别人不配作芙蓉。","quote":{"文":"只見上面畫著一枝芙蓉，題著「風露清愁」四字，那面一句舊詩，道是：莫怨東風當自嗟。","回":63}}}'),旧幅映射:{zanghua:{0:0,1:0,2:7,3:8,4:10,5:4,6:5},pudie:{0:0,1:0,2:1,3:2,4:3,5:4},zuiyan:{0:0,1:0,2:1,3:2,4:3,5:4},youyuan:{0:0,1:0,2:1,3:2,4:3,5:4,6:5},haitang:{0:0,1:1,2:3,3:2,4:3,5:4,6:5},pinchamei:{0:0,1:0,2:1,3:2,4:3,5:4,6:5},lianju:{0:0,1:0,2:1,3:2,4:3,5:4,6:5},aida:{0:0,1:0,2:2,3:4,4:8,5:9,6:10,7:13},zhengmen:{0:0,1:0,2:1,3:2,4:3},gexing:{0:0,1:0,2:1,3:2,4:3,5:4},zhouru:{0:0,1:0,2:1,3:2,4:3,5:4},chufang:{0:0,1:0,2:1,3:2,4:3,5:4},gongdu:{0:0,1:0,2:1,3:2,4:3,5:4},qujing:{0:0,1:0,2:1,3:2,4:3,5:4},fengao:{0:0,1:0,2:1,3:2,4:3,5:4},zilingge:{0:0,1:0,2:1,3:2,4:3},kanhua:{0:0,1:0,2:1,3:2,4:3,5:4},tianran:{0:0,1:0,2:1,3:2,4:3,5:4},chixie:{0:0,1:0,2:1,3:2,4:3,5:4},baiyue:{0:0,1:0,2:1,3:2,4:3,5:4},zhongqiu:{0:0,1:0,2:1,3:2,4:3,5:4,6:5},huaqiang:{0:0,1:0,2:1,3:2,4:3,5:4},xuedong:{0:0,1:0,2:1,3:2,4:3},shengqin:{0:0,1:0,2:1,3:2,4:3,5:4,6:5},yeyan:{0:0,1:0,2:1,3:2,4:3,5:4}}};export{e as default};
